NAME = 'KLV: Klingon Language Version of the World English Bible'
BOOK = 'I Kings'

CHAPTERS = {
    1: {
        1: "DaH joH David ghaHta' qan je mup Daq DISmey; je chaH covered ghaH tlhej clothes, 'ach ghaH couldn't pol warm.",
        2: "vaj Daj toy'wI'pu' ja'ta' Daq ghaH, “chaw' pa' taH nejta' vaD wIj joH the joH a Qup virgin: je chaw' Daj Qam qaSpa' the joH, je cherish ghaH; je chaw' Daj Qot Daq lIj bosom, vetlh wIj joH the joH may pol warm.”",
        3: "vaj chaH nejta' vaD a 'IH Qup lady throughout Hoch the veHmey vo' Israel, je tu'ta' Abishag the Shunammite, je qempu' Daj Daq the joH.",
        4: "The Qup lady ghaHta' very 'IH; je ghaH cherished the joH, je ministered Daq ghaH; 'ach the joH ta'be' Sov Daj intimately.",
        5: "vaj Adonijah the puqloD vo' Haggith exalted himself, ja'ta', “jIH DichDaq taH joH.” vaj ghaH prepared ghaH Dujmey je horsemen, je vaghmaH loDpu' Daq run qaSpa' ghaH.",
        6: "Daj vav ghajta' ghobe' displeased ghaH Daq vay' poH Daq ja'ta', “qatlh ghaj SoH ta'pu' vaj?” je ghaH ghaHta' je a very handsome loD; je ghaH ghaHta' bogh after Absalom.",
        7: "ghaH conferred tlhej Joab the puqloD vo' Zeruiah, je tlhej Abiathar the lalDan vumwI': je chaH following Adonijah helped ghaH.",
        8: "'ach Zadok the lalDan vumwI', je Benaiah the puqloD vo' Jehoiada, je Nathan the leghwI'pu', je Shimei, je Rei, je the HoS loDpu' 'Iv belonged Daq David, were ghobe' tlhej Adonijah.",
        9: "Adonijah HoHta' Suy' je cattle je fatlings Sum the nagh vo' Zoheleth, nuq ghaH retlh En Rogel; je ghaH ja' Hoch Daj loDnI'pu', the joH puqloDpu', je Hoch the loDpu' vo' Judah, the joH toy'wI'pu':",
        10: "'ach Nathan the leghwI'pu', je Benaiah, je the HoS loDpu', je Solomon Daj loDnI', ghaH ta'be' ja'.",
        11: "vaj Nathan jatlhta' Daq Bathsheba the SoS vo' Solomon, ja'ta', “ghajbe' SoH Qoyta' vetlh Adonijah the puqloD vo' Haggith reigns, je David maj joH ta'be' Sov 'oH?",
        12: "DaH vaj ghoS, please chaw' jIH nob SoH qeS, vetlh SoH may toD lIj ghaj yIn, je the yIn vo' lIj puqloD Solomon.",
        13: "jaH Daq Daq joH David, je ja' ghaH, ‘ta'be' SoH, wIj joH, joH, swear Daq lIj handmaid, ja'ta', DIch Solomon lIj puqloD DIchDaq che' after jIH, je ghaH DIchDaq ba' Daq wIj quS'a'? qatlh vaj ta'taH Adonijah che'?'",
        14: "yIlegh, qaStaHvIS SoH yet talk pa' tlhej the joH, jIH je DichDaq ghoS Daq after SoH, je confirm lIj mu'mey.”",
        15: "Bathsheba mejta' Daq Daq the joH Daq the chamber. The joH ghaHta' very qan; je Abishag the Shunammite ghaHta' ministering Daq the joH.",
        16: "Bathsheba bowed, je ta'ta' obeisance Daq the joH. The joH ja'ta', “nuq would SoH rur?”",
        17: "ghaH ja'ta' Daq ghaH, “wIj joH, SoH swore Sum joH'a' lIj joH'a' Daq lIj handmaid, ‘DIch Solomon lIj puqloD DIchDaq che' after jIH, je ghaH DIchDaq ba' Daq wIj quS'a'.'",
        18: "DaH, yIlegh, Adonijah reigns; je SoH, wIj joH the joH, yImev Sov 'oH.",
        19: "ghaH ghajtaH Heghta' cattle je fatlings je Suy' Daq abundance, je ghajtaH ja' Hoch the puqloDpu' vo' the joH, je Abiathar the lalDan vumwI', je Joab the HoD vo' the army; 'ach ghaH ghajbe' ja' Solomon lIj toy'wI'.",
        20: "SoH, wIj joH the joH, the mInDu' vo' Hoch Israel 'oH Daq SoH, vetlh SoH should ja' chaH 'Iv DIchDaq ba' Daq the quS'a' vo' wIj joH the joH after ghaH.",
        21: "Otherwise 'oH DichDaq qaS, ghorgh wIj joH the joH DIchDaq Qong tlhej Daj vavpu', vetlh jIH je wIj puqloD Solomon DIchDaq taH counted offenders.”",
        22: "yIlegh, qaStaHvIS ghaH yet talked tlhej the joH, Nathan the leghwI'pu' ghoSta' Daq.",
        23: "chaH ja'ta' the joH, ja'ta', “yIlegh, Nathan the leghwI'pu'!” ghorgh ghaH ghajta' ghoS Daq qaSpa' the joH, ghaH bowed himself qaSpa' the joH tlhej Daj qab Daq the yav.",
        24: "Nathan ja'ta', “wIj joH, joH, ghaj SoH ja'ta', ‘Adonijah DIchDaq che' after jIH, je ghaH DIchDaq ba' Daq wIj quS'a'?'",
        25: "vaD ghaH ghaH ghoSta' bIng vam jaj, je ghajtaH Heghta' cattle je fatlings je Suy' Daq abundance, je ghajtaH ja' Hoch the joH puqloDpu', je the HoDpu' vo' the army, je Abiathar the lalDan vumwI'. yIlegh, chaH 'oH eating je drinking qaSpa' ghaH, je jatlh, ‘tIq yIn joH Adonijah!'",
        26: "'ach ghaH ghajbe' ja' jIH, 'ach jIH lIj toy'wI', je Zadok the lalDan vumwI', je Benaiah the puqloD vo' Jehoiada, je lIj toy'wI' Solomon.",
        27: "ghaH vam Doch ta'pu' Sum wIj joH the joH, je SoH ghajbe' shown Daq lIj toy'wI'pu' 'Iv should ba' Daq the quS'a' vo' wIj joH the joH after ghaH?”",
        28: "vaj joH David jangta', “ja' Daq jIH Bathsheba.” ghaH ghoSta' Daq the joH Daq, je Qampu' qaSpa' the joH.",
        29: "The joH swore, je ja'ta', “As joH'a' yIn, 'Iv ghajtaH toDta' wIj qa' pa' vo' Hoch adversity,",
        30: "HochHom certainly as jIH swore Daq SoH Sum joH'a', the joH'a' vo' Israel, ja'ta', ‘DIch Solomon lIj puqloD DIchDaq che' after jIH, je ghaH DIchDaq ba' Daq wIj quS'a' Daq wIj Daq;' HochHom certainly vaj DichDaq jIH ta' vam jaj.”",
        31: "vaj Bathsheba bowed tlhej Daj qab Daq the tera', je ta'ta' obeisance Daq the joH, je ja'ta', “chaw' wIj joH joH David yIn reH!”",
        32: "joH David ja'ta', “ja' Daq jIH Zadok the lalDan vumwI', Nathan the leghwI'pu', je Benaiah the puqloD vo' Jehoiada.” chaH ghoSta' qaSpa' the joH.",
        33: "The joH ja'ta' Daq chaH, “tlhap tlhej SoH the toy'wI'pu' vo' lIj joH, je cause Solomon wIj puqloD Daq ride Daq wIj ghaj mule, je qem ghaH bIng Daq Gihon.",
        34: "chaw' Zadok the lalDan vumwI' je Nathan the leghwI'pu' anoint ghaH pa' joH Dung Israel. Blow the trumpet, je jatlh, ‘tIq yIn joH Solomon!'",
        35: "vaj SoH DIchDaq ghoS Dung after ghaH, je ghaH DIchDaq ghoS je ba' Daq wIj quS'a'; vaD ghaH DIchDaq taH joH Daq wIj Daq. jIH ghaj wIv ghaH Daq taH joHHom Dung Israel je Dung Judah.”",
        36: "Benaiah the puqloD vo' Jehoiada jangta' the joH, je ja'ta', “Amen. May joH'a', the joH'a' vo' wIj joH the joH, jatlh vaj.",
        37: "As joH'a' ghajtaH taH tlhej wIj joH the joH, 'ach vaj may ghaH taH tlhej Solomon, je chenmoH Daj quS'a' greater than the quS'a' vo' wIj joH joH David.”",
        38: "vaj Zadok the lalDan vumwI', je Nathan the leghwI'pu', je Benaiah the puqloD vo' Jehoiada, je the Cherethites je the Pelethites, mejta' bIng, je caused Solomon Daq ride Daq joH David's mule, je qempu' ghaH Daq Gihon.",
        39: "Zadok the lalDan vumwI' tlhapta' the horn vo' Hergh pa' vo' the juHHom, je ngoHta' Solomon. chaH blew the trumpet; je Hoch the ghotpu ja'ta', “tIq yIn joH Solomon!”",
        40: "Hoch the ghotpu ghoSta' Dung after ghaH, je the ghotpu piped tlhej pipes, je rejoiced tlhej Dun Quch, vaj vetlh the tera' shook tlhej the wab vo' chaH.",
        41: "Adonijah je Hoch the guests 'Iv were tlhej ghaH Qoyta' 'oH as chaH ghajta' chenmoHta' an pItlh vo' eating. ghorgh Joab Qoyta' the wab vo' the trumpet, ghaH ja'ta', “qatlh ghaH vam noise vo' the veng taH Daq an uproar?”",
        42: "qaStaHvIS ghaH yet jatlhta', yIlegh, Jonathan the puqloD vo' Abiathar the lalDan vumwI' ghoSta': je Adonijah ja'ta', “ghoS Daq; vaD SoH 'oH a worthy loD, je qem QaQ news.”",
        43: "Jonathan jangta' Adonijah, “HochHom certainly maj joH joH David ghajtaH chenmoHta' Solomon joH.",
        44: "The joH ghajtaH ngeHta' tlhej ghaH Zadok the lalDan vumwI', Nathan the leghwI'pu', Benaiah the puqloD vo' Jehoiada, je the Cherethites je the Pelethites; je chaH ghaj caused ghaH Daq ride Daq the joH mule.",
        45: "Zadok the lalDan vumwI' je Nathan the leghwI'pu' ghaj ngoHta' ghaH joH Daq Gihon. chaH ghaj ghoS Dung vo' pa' rejoicing, vaj vetlh the veng rang again. vam ghaH the noise vetlh SoH ghaj Qoyta'.",
        46: "je, Solomon sits Daq the quS'a' vo' the kingdom.",
        47: "Moreover the joH toy'wI'pu' ghoSta' Daq ghurmoH maj joH joH David, ja'ta', ‘May lIj joH'a' chenmoH the pong vo' Solomon better than lIj pong, je chenmoH Daj quS'a' greater than lIj quS'a';' je the joH bowed himself Daq the bed.",
        48: "je thus ja'ta' the joH, ‘ghurtaH taH joH'a', the joH'a' vo' Israel, 'Iv ghajtaH nobpu' wa' Daq ba' Daq wIj quS'a' vam jaj, wIj mInDu' 'ach leghtaH 'oH.'”",
        49: "Hoch the guests vo' Adonijah were vIp, je rose Dung, je each loD mejta' Daj way.",
        50: "Adonijah feared because vo' Solomon; je ghaH Hu', je mejta', je caught 'uch Daq the horns vo' the lalDanta' Daq.",
        51: "'oH ghaHta' ja'ta' Solomon, ja'ta', “yIlegh, Adonijah fears joH Solomon; vaD, yIlegh, ghaH ghajtaH laid 'uch Daq the horns vo' the lalDanta' Daq, ja'ta', ‘chaw' joH Solomon swear Daq jIH wa'Dich vetlh ghaH DichDaq ghobe' HoH Daj toy'wI' tlhej the 'etlh.'”",
        52: "Solomon ja'ta', “chugh ghaH shows himself a worthy loD, pa' DIchDaq ghobe' a jIb vo' ghaH pum Daq the tera'; 'ach chugh mIghtaHghach taH tu'ta' Daq ghaH, ghaH DIchDaq Hegh.”",
        53: "vaj joH Solomon ngeHta', je chaH qempu' ghaH bIng vo' the lalDanta' Daq. ghaH ghoSta' je ta'ta' obeisance Daq joH Solomon; je Solomon ja'ta' Daq ghaH, “jaH Daq lIj tuq.”",
    },
    2: {
        1: "DaH the jajmey vo' David drew Sum vetlh ghaH should Hegh; je ghaH ra'ta' Solomon Daj puqloD, ja'ta',",
        2: "“jIH 'oH ghoS the way vo' Hoch the tera'. SoH taH HoS vaj, je cha' SoH'egh a loD;",
        3: "je pol the instruction vo' joH'a' lIj joH'a', Daq yIt Daq Daj Hemey, Daq pol Daj chutmey, Daj ra'ta'ghach mu'mey, Daj chutmey, je Daj testimonies, according Daq vetlh nuq ghaH ghItlhta' Daq the chut vo' Moses, vetlh SoH may chep Daq Hoch vetlh SoH ta', je wherever SoH tlhe' SoH'egh.",
        4: "vetlh joH'a' may establish Daj mu' nuq ghaH jatlhta' concerning jIH, ja'ta', ‘chugh lIj puqpu' tlhap heed Daq chaj way, Daq yIt qaSpa' jIH Daq vIt tlhej Hoch chaj tIq je tlhej Hoch chaj qa', pa' DIchDaq ghobe' fail SoH,' ghaH ja'ta', ‘a loD Daq the quS'a' vo' Israel.'",
        5: "“Moreover SoH Sov je nuq Joab the puqloD vo' Zeruiah ta'ta' Daq jIH, 'ach nuq ghaH ta'ta' Daq the cha' HoDpu' vo' the armies vo' Israel, Daq Abner the puqloD vo' Ner, je Daq Amasa the puqloD vo' Jether, 'Iv ghaH HoHta', je shed the 'Iw vo' veS Daq roj, je lan the 'Iw vo' veS Daq Daj sash vetlh ghaHta' about Daj waist, je Daq Daj shoes vetlh were Daq Daj qamDu'.",
        6: "ta' vaj according Daq lIj valtaHghach, je yImev chaw' Daj gray nach jaH bIng Daq Sheol { Note: Sheol ghaH the Daq vo' the Heghpu'. } Daq roj.",
        7: "'ach cha' pung Daq the puqloDpu' vo' Barzillai the Gileadite, je chaw' chaH taH vo' chaH 'Iv Sop Daq lIj SopDaq; vaD vaj chaH ghoSta' Daq jIH ghorgh jIH Haw'ta' vo' Absalom lIj loDnI'.",
        8: "“yIlegh, pa' ghaH tlhej SoH Shimei the puqloD vo' Gera, the Benjamite, vo' Bahurim, 'Iv cursed jIH tlhej a grievous mu'qaD Daq the jaj ghorgh jIH mejta' Daq Mahanaim; 'ach ghaH ghoSta' bIng Daq ghom jIH Daq the Jordan, je jIH swore Daq ghaH Sum joH'a', ja'ta', ‘jIH DichDaq ghobe' lan SoH Daq Hegh tlhej the 'etlh.'",
        9: "DaH vaj yImev 'uch ghaH guiltless, vaD SoH 'oH a val loD; je SoH DichDaq Sov nuq SoH ought Daq ta' Daq ghaH, je SoH DIchDaq qem Daj gray nach bIng Daq Sheol { Note: Sheol ghaH the Daq vo' the Heghpu'. } tlhej 'Iw.”",
        10: "David Qongta' tlhej Daj vavpu', je ghaHta' buried Daq the veng vo' David.",
        11: "The jajmey vetlh David che'ta' Dung Israel were loSmaH DISmey; Soch DISmey che'ta' ghaH Daq Hebron, je wejmaH- wej DISmey che'ta' ghaH Daq Jerusalem.",
        12: "Solomon ba'ta' Daq the quS'a' vo' David Daj vav; je Daj kingdom ghaHta' firmly established.",
        13: "vaj Adonijah the puqloD vo' Haggith ghoSta' Daq Bathsheba the SoS vo' Solomon. ghaH ja'ta', “ta' SoH ghoS peaceably?” ghaH ja'ta', “Peaceably.",
        14: "ghaH ja'ta' moreover, jIH ghaj something Daq ja' SoH.” ghaH ja'ta', “jatlh Daq.”",
        15: "ghaH ja'ta', “SoH Sov vetlh the kingdom ghaHta' mine, je vetlh Hoch Israel cher chaj faces Daq jIH, vetlh jIH should che'. However the kingdom ghaH tlhe'ta' around, je ghajtaH moj wIj brother's; vaD 'oH ghaHta' Daj vo' joH'a'.",
        16: "DaH jIH tlhob wa' petition vo' SoH. yImev deny jIH.” ghaH ja'ta' Daq ghaH, “jatlh Daq.”",
        17: "ghaH ja'ta', “Please jatlh Daq Solomon the joH (vaD ghaH DichDaq ghobe' ja' SoH ‘no'), vetlh ghaH nob jIH Abishag the Shunammite as be'nal.”",
        18: "Bathsheba ja'ta', “Alright. jIH DichDaq jatlh vaD SoH Daq the joH.”",
        19: "Bathsheba vaj mejta' Daq joH Solomon, Daq jatlh Daq ghaH vaD Adonijah. The joH rose Dung Daq ghom Daj, je bowed himself Daq Daj, je ba'ta' bIng Daq Daj quS'a', je caused a quS'a' Daq taH cher vaD the joH SoS; je ghaH ba'ta' Daq Daj nIH ghop.",
        20: "vaj ghaH ja'ta', “jIH tlhob wa' mach petition vo' SoH; yImev deny jIH.” The joH ja'ta' Daq Daj, “tlhob Daq, wIj SoS; vaD jIH DichDaq ghobe' deny SoH.”",
        21: "ghaH ja'ta', “chaw' Abishag the Shunammite taH nobpu' Daq Adonijah lIj loDnI' as be'nal.”",
        22: "joH Solomon jangta' Daj SoS, “qatlh ta' SoH tlhob Abishag the Shunammite vaD Adonijah? tlhob vaD ghaH the kingdom je; vaD ghaH ghaH wIj elder loDnI'; 'ach vaD ghaH, je vaD Abiathar the lalDan vumwI', je vaD Joab the puqloD vo' Zeruiah.”",
        23: "vaj joH Solomon swore Sum joH'a', ja'ta', “joH'a' ta' vaj Daq jIH, je latlh je, chugh Adonijah ghajtaH ghobe' jatlhpu' vam mu' Daq Daj ghaj yIn.",
        24: "DaH vaj as joH'a' yIn, 'Iv ghajtaH established jIH, je cher jIH Daq the quS'a' vo' David wIj vav, je 'Iv ghajtaH chenmoHta' jIH a tuq, as ghaH promised, DIch Adonijah DIchDaq taH lan Daq Hegh vam jaj.”",
        25: "joH Solomon ngeHta' Sum Benaiah the puqloD vo' Jehoiada; je ghaH pumta' Daq ghaH, vaj vetlh ghaH Heghta'.",
        26: "Daq Abiathar the lalDan vumwI' the joH ja'ta', “jaH Daq Anathoth, Daq lIj ghaj fields; vaD SoH 'oH worthy vo' Hegh. 'ach jIH DichDaq ghobe' Daq vam poH lan SoH Daq Hegh, because SoH boghmoH the Duj vo' the joH joH'a' qaSpa' David wIj vav, je because SoH were afflicted Daq Hoch Daq nuq wIj vav ghaHta' afflicted.”",
        27: "vaj Solomon thrust pa' Abiathar vo' taH lalDan vumwI' Daq joH'a', vetlh ghaH might fulfill the mu' vo' joH'a', nuq ghaH jatlhta' concerning the tuq vo' Eli Daq Shiloh.",
        28: "The news ghoSta' Daq Joab; vaD Joab ghajta' tlhe'ta' after Adonijah, 'a' ghaH ta'be' tlhe' after Absalom. Joab Haw'ta' Daq the juHHom vo' joH'a', je caught 'uch Daq the horns vo' the lalDanta' Daq.",
        29: "'oH ghaHta' ja'ta' joH Solomon, “Joab ghajtaH Haw'ta' Daq the juHHom vo' joH'a', je yIlegh, ghaH ghaH Sum the lalDanta' Daq.” vaj Solomon ngeHta' Benaiah the puqloD vo' Jehoiada, ja'ta', “jaH, pum Daq ghaH.”",
        30: "Benaiah ghoSta' Daq the juHHom vo' joH'a', je ja'ta' Daq ghaH, “Thus jatlhtaH the joH, ‘ghoS vo'!'” ghaH ja'ta', “ghobe'; 'ach jIH DichDaq Hegh naDev.” Benaiah qempu' the joH mu' again, ja'ta', “Thus ja'ta' Joab, je thus ghaH jangta' jIH.”",
        31: "The joH ja'ta' Daq ghaH, “ta' as ghaH ghajtaH ja'ta', je pum Daq ghaH, je bury ghaH; vetlh SoH may tlhap DoH the 'Iw, nuq Joab shed Hutlh cause, vo' jIH je vo' wIj vav tuq.",
        32: "joH'a' DichDaq chegh Daj 'Iw Daq Daj ghaj nach, because ghaH pumta' Daq cha' loDpu' latlh QaQtaHghach je better than ghaH, je HoHta' chaH tlhej the 'etlh, je wIj vav David ta'be' Sov 'oH: Abner the puqloD vo' Ner, HoD vo' the army vo' Israel, je Amasa the puqloD vo' Jether, HoD vo' the army vo' Judah.",
        33: "vaj DIchDaq chaj 'Iw chegh Daq the nach vo' Joab, je Daq the nach vo' Daj tIr reH. 'ach Daq David, je Daq Daj tIr, je Daq Daj tuq, je Daq Daj quS'a', pa' DIchDaq taH roj reH vo' joH'a'.”",
        34: "vaj Benaiah the puqloD vo' Jehoiada mejta' Dung, je pumta' Daq ghaH, je HoHta' ghaH; je ghaH ghaHta' buried Daq Daj ghaj tuq Daq the ngem.",
        35: "The joH lan Benaiah the puqloD vo' Jehoiada Daq Daj room Dung the army; je Zadok the lalDan vumwI' ta'ta' the joH lan Daq the room vo' Abiathar.",
        36: "The joH ngeHta' je ja' vaD Shimei, je ja'ta' Daq ghaH, “chen SoH'egh a tuq Daq Jerusalem, je yIn pa', je yImev jaH pa' vo' pa' anywhere.",
        37: "vaD Daq the jaj SoH jaH pa', je juS Dung the brook Kidron, Sov vaD Dich vetlh SoH DIchDaq DIch Hegh: lIj 'Iw DIchDaq taH Daq lIj ghaj nach.”",
        38: "Shimei ja'ta' Daq the joH, “The ja'ta' ghaH QaQ. As wIj joH the joH ghajtaH ja'ta', vaj DichDaq lIj toy'wI' ta'.” Shimei yInta' Daq Jerusalem law' jajmey.",
        39: "'oH qaSta' Daq the pItlh vo' wej DISmey, vetlh cha' vo' the toy'wI'pu' vo' Shimei ran DoH Daq Achish, puqloD vo' Maacah, joH vo' Gath. chaH ja'ta' Shimei, ja'ta', “yIlegh, lIj toy'wI'pu' 'oH Daq Gath.”",
        40: "Shimei Hu', je saddled Daj SarghHom, je mejta' Daq Gath Daq Achish, Daq nej Daj toy'wI'pu'; je Shimei mejta', je qempu' Daj toy'wI'pu' vo' Gath.",
        41: "'oH ghaHta' ja'ta' Solomon vetlh Shimei ghajta' ghoSta' vo' Jerusalem Daq Gath, je ghaHta' ghoS again.",
        42: "The joH ngeHta' je ja' vaD Shimei, je ja'ta' Daq ghaH, “ta'be' jIH adjure SoH Sum joH'a', je warn SoH, ja'ta', ‘Sov vaD Dich, vetlh Daq the jaj SoH jaH pa', je yIt abroad vay' nuqDaq, SoH DIchDaq DIch Hegh?' SoH ja'ta' Daq jIH, ‘The ja'ta' vetlh jIH ghaj Qoyta' ghaH QaQ.'",
        43: "qatlh vaj ghaj SoH ghobe' polta' the oath vo' joH'a', je the ra'ta'ghach mu' vetlh jIH ghaj instructed SoH tlhej?”",
        44: "The joH ja'ta' moreover Daq Shimei, “SoH Sov Hoch the mIghtaHghach nuq lIj tIq ghaH privy Daq, vetlh SoH ta'ta' Daq David wIj vav. vaj joH'a' DIchDaq chegh lIj mIghtaHghach Daq lIj ghaj nach.",
        45: "'ach joH Solomon DIchDaq taH ghurtaH, je the quS'a' vo' David DIchDaq taH established qaSpa' joH'a' reH.”",
        46: "vaj the joH ra'ta' Benaiah the puqloD vo' Jehoiada; je ghaH mejta' pa', je pumta' Daq ghaH, vaj vetlh ghaH Heghta'. The kingdom ghaHta' established Daq the ghop vo' Solomon.",
    },
    3: {
        1: "Solomon chenmoHta' affinity tlhej Pharaoh joH vo' Egypt, je tlhapta' Pharaoh's puqbe', je qempu' Daj Daq the veng vo' David, until ghaH ghajta' chenmoHta' an pItlh vo' building Daj ghaj tuq, je the tuq vo' joH'a', je the reD vo' Jerusalem Hoch around.",
        2: "neH the ghotpu sacrificed Daq the jen Daqmey, because pa' ghaHta' ghobe' tuq chenta' vaD the pong vo' joH'a' until chaH jajmey.",
        3: "Solomon loved joH'a', walking Daq the chutmey vo' David Daj vav: neH ghaH sacrificed je meQqu'pu' He' Daq the jen Daqmey.",
        4: "The joH mejta' Daq Gibeon Daq sacrifice pa'; vaD vetlh ghaHta' the Dun jen Daq: a SaD meQqu'pu' nobmey ta'ta' Solomon nob Daq vetlh lalDanta' Daq.",
        5: "Daq Gibeon joH'a' appeared Daq Solomon Daq a dream Sum ram; je joH'a' ja'ta', “tlhob nuq jIH DIchDaq nob SoH.”",
        6: "Solomon ja'ta', “SoH ghaj shown Daq lIj toy'wI' David wIj vav Dun muSHa'taH pung, according as ghaH yItta' qaSpa' SoH Daq vIt, je Daq QaQtaHghach, je Daq uprightness vo' tIq tlhej SoH. SoH ghaj polta' vaD ghaH vam Dun muSHa'taH pung, vetlh SoH ghaj nobpu' ghaH a puqloD Daq ba' Daq Daj quS'a', as 'oH ghaH vam jaj.",
        7: "DaH, joH'a' wIj joH'a', SoH ghaj chenmoHta' lIj toy'wI' joH instead vo' David wIj vav. jIH 'oH 'ach a mach puq. jIH yImev Sov chay' Daq jaH pa' joq ghoS Daq.",
        8: "lIj toy'wI' ghaH Daq the midst vo' lIj ghotpu nuq SoH ghaj wIvpu', a Dun ghotpu, vetlh ta'laHbe' taH toghta' ghobe' counted vaD qevmey.",
        9: "nob lIj toy'wI' vaj an yajtaHghach tIq Daq noH lIj ghotpu, vetlh jIH may discern joj QaQ je mIghtaHghach; vaD 'Iv ghaH laH Daq noH vam lIj Dun ghotpu?”",
        10: "The speech pleased the joH, vetlh Solomon ghajta' tlhobta' vam Doch.",
        11: "joH'a' ja'ta' Daq ghaH, “Because SoH ghaj tlhobta' vam Doch, je ghaj ghobe' tlhobta' vaD SoH'egh tIq yIn, ghobe' ghaj tlhobta' riches vaD SoH'egh, ghobe' ghaj tlhobta' the yIn vo' lIj jaghpu', 'ach ghaj tlhobta' vaD SoH'egh yajtaHghach Daq discern ruv;",
        12: "yIlegh, jIH ghaj ta'pu' according Daq lIj mu'. yIlegh, jIH ghaj nobpu' SoH a val je an yajtaHghach tIq; vaj vetlh pa' ghajtaH taH pagh rur SoH qaSpa' SoH, ghobe' after SoH DIchDaq vay' Hu' rur SoH.",
        13: "jIH ghaj je nobpu' SoH vetlh nuq SoH ghaj ghobe' tlhobta', both riches je quv, vaj vetlh pa' DIchDaq ghobe' taH vay' among the joHpu' rur SoH, Hoch lIj jajmey.",
        14: "chugh SoH DichDaq yIt Daq wIj Hemey, Daq pol wIj chutmey je wIj ra'ta'ghach mu'mey, as lIj vav David yItta', vaj jIH DichDaq lengthen lIj jajmey.”",
        15: "Solomon awoke; je yIlegh, 'oH ghaHta' a dream. vaj ghaH ghoSta' Daq Jerusalem, je Qampu' qaSpa' the Duj vo' the lay' vo' joH'a', je nobta' Dung meQqu'pu' nobmey, nobta' roj nobmey, je chenmoHta' a 'uQ'a' Daq Hoch Daj toy'wI'pu'.",
        16: "vaj cha' be'pu' 'Iv were prostitutes ghoSta' Daq the joH, je Qampu' qaSpa' ghaH.",
        17: "The wa' be' ja'ta', “Oh, wIj joH, jIH je vam be' yIn Daq wa' tuq. jIH toDta' a puq tlhej Daj Daq the tuq.",
        18: "'oH qaSta' the wejDIch jaj after jIH toDta', vetlh vam be' toDta' je. maH were tay'. pa' ghaHta' ghobe' stranger tlhej maH Daq the tuq, just maH cha' Daq the tuq.",
        19: "vam woman's puq Heghta' Daq the ram, because ghaH lay Daq 'oH.",
        20: "ghaH Hu' Daq midnight, je tlhapta' wIj puqloD vo' retlh jIH, qaStaHvIS lIj handmaid Qongta', je laid 'oH Daq Daj bosom, je laid Daj Heghpu' puq Daq wIj bosom.",
        21: "ghorgh jIH rose Daq the po Daq nurse wIj puq, yIlegh, 'oH ghaHta' Heghpu'; 'ach ghorgh jIH ghajta' nejta' Daq 'oH Daq the po, yIlegh, 'oH ghaHta' ghobe' wIj puqloD, 'Iv jIH boghmoH.”",
        22: "The latlh be' ja'ta', “ghobe'; 'ach the yIntaH ghaH wIj puqloD, je the Heghpu' ghaH lIj puqloD.” vam ja'ta', “ghobe'; 'ach the Heghpu' ghaH lIj puqloD, je the yIntaH ghaH wIj puqloD.” Thus chaH jatlhta' qaSpa' the joH.",
        23: "vaj the joH ja'ta', “The wa' jatlhtaH, ‘vam ghaH wIj puqloD 'Iv yIn, je lIj puqloD ghaH the Heghpu';' je the latlh jatlhtaH, ‘ghobe'; 'ach lIj puqloD ghaH the Heghpu' wa', je wIj puqloD ghaH the yIntaH wa'.'”",
        24: "The joH ja'ta', “tlhap jIH a 'etlh.” chaH qempu' a 'etlh qaSpa' the joH.",
        25: "The joH ja'ta', “Divide the yIntaH puq Daq cha', je nob bID Daq the wa', je bID Daq the latlh.”",
        26: "vaj the be' 'Iv the yIntaH puq ghaHta' jatlhta' Daq the joH, vaD Daj tIq yearned Dung Daj puqloD, je ghaH ja'ta', “Oh, wIj joH, nob Daj the yIntaH puq, je Daq ghobe' way HoH 'oH!” 'ach the latlh ja'ta', “'oH DIchDaq taH ghobe' mine ghobe' yours. Divide 'oH.”",
        27: "vaj the joH jangta', “nob Daj the yIntaH puq, je Daq ghobe' way HoH 'oH. ghaH ghaH its SoS.”",
        28: "Hoch Israel Qoyta' vo' the yoj nuq the joH ghajta' judged; je chaH feared the joH: vaD chaH leghta' vetlh the valtaHghach vo' joH'a' ghaHta' Daq ghaH, Daq ta' ruv.",
    },
    4: {
        1: "joH Solomon ghaHta' joH Dung Hoch Israel.",
        2: "Dochvammey were the joHHom 'Iv ghaH ghajta': Azariah the puqloD vo' Zadok, the lalDan vumwI';",
        3: "Elihoreph je Ahijah, the puqloDpu' vo' Shisha, scribes; Jehoshaphat the puqloD vo' Ahilud, the recorder;",
        4: "je Benaiah the puqloD vo' Jehoiada ghaHta' Dung the army; je Zadok je Abiathar were lalDan vumwI'pu';",
        5: "je Azariah the puqloD vo' Nathan ghaHta' Dung the officers; je Zabud the puqloD vo' Nathan ghaHta' pIn minister, je the joH friend;",
        6: "je Ahishar ghaHta' Dung the household; je Adoniram the puqloD vo' Abda ghaHta' Dung the loDpu' subject Daq forced labor.",
        7: "Solomon ghajta' cha' wa'maH officers Dung Hoch Israel, 'Iv provided Soj vaD the joH je Daj household: each loD ghajta' Daq chenmoH provision vaD a jar Daq the DIS.",
        8: "Dochvammey 'oH chaj pongmey: Ben Hur, Daq the HuD Hatlh vo' Ephraim;",
        9: 'Ben Deker, Daq Makaz, je Daq Shaalbim, je Beth Shemesh, je Elon Beth Hanan;',
        10: "Ben Hesed, Daq Arubboth (Daq ghaH pertained Socoh, je Hoch the puH vo' Hepher);",
        11: "Ben Abinadab, Daq Hoch the height vo' Dor (ghaH ghajta' Taphath the puqbe' vo' Solomon as be'nal);",
        12: "Baana the puqloD vo' Ahilud, Daq Taanach je Megiddo, je Hoch Beth Shean nuq ghaH retlh Zarethan, bIng Jezreel, vo' Beth Shean Daq Abel Meholah, as Hop as beyond Jokmeam;",
        13: "Ben Geber, Daq Ramoth Gilead (Daq ghaH pertained the towns vo' Jair the puqloD vo' Manasseh, nuq 'oH Daq Gilead; 'ach Daq ghaH pertained the region vo' Argob, nuq ghaH Daq Bashan, javmaH Dun vengmey tlhej walls je bronze bars);",
        14: "Ahinadab the puqloD vo' Iddo, Daq Mahanaim;",
        15: "Ahimaaz, Daq Naphtali (ghaH je tlhapta' Basemath the puqbe' vo' Solomon as be'nal);",
        16: "Baana the puqloD vo' Hushai, Daq Asher je Bealoth;",
        17: "Jehoshaphat the puqloD vo' Paruah, Daq Issachar;",
        18: "Shimei the puqloD vo' Ela, Daq Benjamin;",
        19: "Geber the puqloD vo' Uri, Daq the puH vo' Gilead, the Hatlh vo' Sihon joH vo' the Amorites je vo' Og joH vo' Bashan; je ghaH ghaHta' the neH officer 'Iv ghaHta' Daq the puH.",
        20: "Judah je Israel were law' as the sand nuq ghaH Sum the biQ'a' Daq qevmey, eating je drinking je making yItIv.",
        21: "Solomon ruled Dung Hoch the kingdoms vo' the bIQtIQ Daq the puH vo' the Philistines, je Daq the veH vo' Egypt: chaH qempu' tribute, je served Solomon Hoch the jajmey vo' Daj yIn.",
        22: "Solomon's provision vaD wa' jaj ghaHta' wejmaH juvtaH vo' fine flour, je javmaH juvtaH vo' 'uQ,",
        23: "wa'maH nach vo' ror cattle, je cha'maH nach vo' cattle pa' vo' the tI yotlh, je wa' vatlh Suy', je harts, je gazelles, je roebucks, je fattened fowl.",
        24: "vaD ghaH ghajta' dominion Dung Hoch the region Daq vam retlh the bIQtIQ, vo' Tiphsah 'ach Daq Gaza, Dung Hoch the joHpu' Daq vam retlh the bIQtIQ: je ghaH ghajta' roj Daq Hoch sides around ghaH.",
        25: "Judah je Israel yInta' safely, Hoch loD bIng Daj vine je bIng Daj fig Sor, vo' Dan 'ach Daq Beersheba, Hoch the jajmey vo' Solomon.",
        26: "Solomon ghajta' loSmaH SaD stalls vo' horses vaD Daj Dujmey, je cha' wa'maH SaD horsemen.",
        27: "chaH officers provided Soj vaD joH Solomon, je vaD Hoch 'Iv ghoSta' Daq joH Solomon's SopDaq, Hoch loD Daq Daj jar; chaH chaw' pagh taH lacking.",
        28: "Barley je je straw vaD the horses je swift steeds qempu' chaH Daq the Daq nuqDaq the officers were, Hoch loD according Daq Daj duty.",
        29: "joH'a' nobta' Solomon valtaHghach je yajtaHghach exceeding 'ar, je very Dun yajtaHghach, 'ach as the sand vetlh ghaH Daq the seashore.",
        30: "Solomon's valtaHghach excelled the valtaHghach vo' Hoch the puqpu' vo' the pemHov 'o', je Hoch the valtaHghach vo' Egypt.",
        31: "vaD ghaH ghaHta' wiser than Hoch loDpu'; than Ethan the Ezrahite, je Heman, je Calcol, je Darda, the puqloDpu' vo' Mahol: je Daj fame ghaHta' Daq Hoch the tuqpu' Hoch around.",
        32: "ghaH jatlhta' wej SaD proverbs; je Daj bommey were wa' SaD vagh.",
        33: "ghaH jatlhta' vo' Sormey, vo' the cedar vetlh ghaH Daq Lebanon 'ach Daq the hyssop vetlh springs pa' vo' the reD; ghaH jatlhta' je vo' Ha'DIbaH, je vo' toQmey, je vo' creeping Dochmey, je vo' fish.",
        34: "pa' ghoSta' vo' Hoch ghotpu' Daq Qoy the valtaHghach vo' Solomon, vo' Hoch joHpu' vo' the tera', 'Iv ghajta' Qoyta' vo' Daj valtaHghach.",
    },
    5: {
        1: "Hiram joH vo' Tyre ngeHta' Daj toy'wI'pu' Daq Solomon; vaD ghaH ghajta' Qoyta' vetlh chaH ghajta' ngoHta' ghaH joH Daq the room vo' Daj vav: vaD Hiram ghaHta' ever a lover vo' David.",
        2: "Solomon ngeHta' Daq Hiram, ja'ta',",
        3: "“SoH Sov chay' vetlh David wIj vav laH ghobe' chen a tuq vaD the pong vo' joH'a' Daj joH'a' vaD the wars nuq were about ghaH Daq Hoch retlh, until joH'a' lan chaH bIng the soles vo' Daj qamDu'.",
        4: "'ach DaH joH'a' wIj joH'a' ghajtaH nobpu' jIH leS Daq Hoch retlh. pa' ghaH ghobe' jagh, ghobe' mIghtaHghach occurrence.",
        5: "yIlegh, jIH purpose Daq chen a tuq vaD the pong vo' joH'a' wIj joH'a', as joH'a' jatlhta' Daq David wIj vav, ja'ta', ‘lIj puqloD, 'Iv jIH DichDaq cher Daq lIj quS'a' Daq lIj room, ghaH DIchDaq chen the tuq vaD wIj pong.'",
        6: "DaH vaj ra'ta'ghach mu'mey vetlh chaH pe' jIH cedar Sormey pa' vo' Lebanon. wIj toy'wI'pu' DIchDaq taH tlhej lIj toy'wI'pu'; je jIH DichDaq nob SoH wages vaD lIj toy'wI'pu' according Daq Hoch vetlh SoH DIchDaq jatlh. vaD SoH Sov vetlh pa' ghaH ghobe' among maH vay' 'Iv SovtaH chay' Daq pe' timber rur the Sidonians.”",
        7: "'oH qaSta', ghorgh Hiram Qoyta' the mu'mey vo' Solomon, vetlh ghaH rejoiced greatly, je ja'ta', “ghurtaH ghaH joH'a' vam jaj, 'Iv ghajtaH nobpu' Daq David a val puqloD Dung vam Dun ghotpu.”",
        8: "Hiram ngeHta' Daq Solomon, ja'ta', “jIH ghaj Qoyta' the message nuq SoH ghaj ngeHta' Daq jIH. jIH DichDaq ta' Hoch lIj neH concerning timber vo' cedar, je concerning timber vo' fir.",
        9: "wIj toy'wI'pu' DIchDaq qem chaH bIng vo' Lebanon Daq the biQ'a'. jIH DichDaq chenmoH chaH Daq rafts Daq jaH Sum biQ'a' Daq the Daq vetlh SoH DIchDaq appoint jIH, je DichDaq cause chaH Daq taH ghorta' Dung pa', je SoH DIchDaq Hev chaH. SoH DIchDaq accomplish wIj neH, Daq giving Soj vaD wIj household.”",
        10: "vaj Hiram nobta' Solomon timber vo' cedar je timber vo' fir according Daq Hoch Daj neH.",
        11: "Solomon nobta' Hiram cha'maH SaD juvtaH vo' wheat vaD Soj Daq Daj household, je cha'maH juvtaH vo' pure Hergh. Solomon nobta' vam Daq Hiram DIS Sum DIS.",
        12: "joH'a' nobta' Solomon valtaHghach, as ghaH promised ghaH; je pa' ghaHta' roj joj Hiram je Solomon; je chaH cha' chenmoHta' a league tay'.",
        13: "joH Solomon raised a levy pa' vo' Hoch Israel; je the levy ghaHta' wejmaH SaD loDpu'.",
        14: "ghaH ngeHta' chaH Daq Lebanon, wa'maH SaD a jar Sum courses; a jar chaH were Daq Lebanon, je cha' months Daq home; je Adoniram ghaHta' Dung the loDpu' subject Daq forced labor.",
        15: "Solomon ghajta' seventy SaD 'Iv boghmoH burdens, je eighty SaD 'Iv were nagh cutters Daq the Hudmey;",
        16: "je Solomon's pIn officers 'Iv were Dung the vum, wej SaD je wej vatlh, 'Iv boghmoH rule Dung the ghotpu 'Iv labored Daq the vum.",
        17: "The joH ra'ta', je chaH pe' pa' Dun naghmey, costly naghmey, Daq lay the foundation vo' the tuq tlhej worked nagh.",
        18: "Solomon's builders je Hiram's builders je the Gebalites ta'ta' fashion chaH, je prepared the timber je the naghmey Daq chen the tuq.",
    },
    6: {
        1: "'oH qaSta' Daq the loS vatlh je eightieth DIS after the puqpu' vo' Israel were ghoS pa' vo' the puH vo' Egypt, Daq the fourth DIS vo' Solomon's che' Dung Israel, Daq the jar Ziv, nuq ghaH the cha'DIch jar, vetlh ghaH taghta' Daq chen the tuq vo' joH'a'.",
        2: "The tuq nuq joH Solomon chenta' vaD joH'a', its length ghaHta' javmaH cubits, je its breadth cha'maH cubits, je its height wejmaH cubits.",
        3: "The porch qaSpa' the lalDan qach vo' the tuq, cha'maH cubits ghaHta' its length, according Daq the breadth vo' the tuq; je wa'maH cubits ghaHta' its breadth qaSpa' the tuq.",
        4: "vaD the tuq ghaH chenmoHta' windows vo' fixed lattice vum.",
        5: "Daq the reD vo' the tuq ghaH chenta' stories Hoch around, Daq the walls vo' the tuq Hoch around, both vo' the lalDan qach je vo' the oracle; je ghaH chenmoHta' retlh chambers Hoch around.",
        6: "The nethermost story ghaHta' vagh cubits broad, je the middle ghaHta' jav cubits broad, je the wejDIch ghaHta' Soch cubits broad; vaD Daq the outside ghaH chenmoHta' offsets Daq the reD vo' the tuq Hoch around, vetlh the beams should ghobe' ghaj 'uch Daq the walls vo' the tuq.",
        7: "The tuq, ghorgh 'oH ghaHta' Daq building, ghaHta' chenta' vo' nagh chenmoHta' ready Daq the quarry; je pa' ghaHta' ghobe' hammer ghobe' axe ghobe' vay' tool vo' iron Qoyta' Daq the tuq, qaStaHvIS 'oH ghaHta' Daq building.",
        8: "The lojmIt vaD the middle retlh chambers ghaHta' Daq the nIH retlh vo' the tuq: je chaH mejta' Dung Sum winding stairs Daq the middle story, je pa' vo' the middle Daq the wejDIch.",
        9: "vaj ghaH chenta' the tuq, je finished 'oH; je ghaH covered the tuq tlhej beams je planks vo' cedar.",
        10: "ghaH chenta' the stories Daq Hoch the tuq, each vagh cubits jen: je chaH rested Daq the tuq tlhej timber vo' cedar.",
        11: "The mu' vo' joH'a' ghoSta' Daq Solomon, ja'ta',",
        12: "“Concerning vam tuq nuq SoH 'oH building, chugh SoH DichDaq yIt Daq wIj chutmey, je execute wIj chutmey, je pol Hoch wIj ra'ta'ghach mu'mey Daq yIt Daq chaH; vaj DichDaq jIH establish wIj mu' tlhej SoH, nuq jIH jatlhta' Daq David lIj vav.",
        13: "jIH DichDaq yIn among the puqpu' vo' Israel, je DichDaq ghobe' lon wIj ghotpu Israel.”",
        14: "vaj Solomon chenta' the tuq, je finished 'oH.",
        15: "ghaH chenta' the walls vo' the tuq within tlhej boards vo' cedar: vo' the floor vo' the tuq Daq the walls vo' the ceiling, ghaH covered chaH Daq the inside tlhej wood; je ghaH covered the floor vo' the tuq tlhej boards vo' fir.",
        16: "ghaH chenta' cha'maH cubits Daq the hinder part vo' the tuq tlhej boards vo' cedar vo' the floor Daq the walls vo' the ceiling: ghaH chenta' chaH vaD 'oH within, vaD an oracle, 'ach vaD the HochHom le' Daq.",
        17: "The tuq, vetlh ghaH, the lalDan qach qaSpa' the oracle, ghaHta' loSmaH cubits tIq.",
        18: "pa' ghaHta' cedar Daq the tuq within, carved tlhej buds je poSmoH flowers: Hoch ghaHta' cedar; pa' ghaHta' ghobe' nagh leghpu'.",
        19: "ghaH prepared an oracle Daq the midst vo' the tuq within, Daq cher pa' the Duj vo' the lay' vo' joH'a'.",
        20: "Within the oracle ghaHta' a space vo' cha'maH cubits Daq length, je cha'maH cubits Daq breadth, je cha'maH cubits Daq its height; je ghaH overlaid 'oH tlhej pure SuD baS: je ghaH covered the lalDanta' Daq tlhej cedar.",
        21: "vaj Solomon overlaid the tuq within tlhej pure SuD baS: je ghaH drew chains vo' SuD baS across qaSpa' the oracle; je ghaH overlaid 'oH tlhej SuD baS.",
        22: "The Hoch tuq ghaH overlaid tlhej SuD baS, until Hoch the tuq ghaHta' finished: je the Hoch lalDanta' Daq vetlh belonged Daq the oracle ghaH overlaid tlhej SuD baS.",
        23: "Daq the oracle ghaH chenmoHta' cha' cherubim vo' olive wood, each wa'maH cubits jen.",
        24: "vagh cubits ghaHta' the wa' wing vo' the cherub, je vagh cubits the latlh wing vo' the cherub: vo' the uttermost part vo' the wa' wing Daq the uttermost part vo' the latlh were wa'maH cubits.",
        25: "The latlh cherub ghaHta' wa'maH cubits: both the cherubim were vo' wa' juv je wa' form.",
        26: "The height vo' the wa' cherub ghaHta' wa'maH cubits, je vaj ghaHta' 'oH vo' the latlh cherub.",
        27: "ghaH cher the cherubim within the inner tuq; je the telDu' vo' the cherubim were stretched vo', vaj vetlh the wing vo' the wa' touched the wa' reD, je the wing vo' the latlh cherub touched the latlh reD; je chaj telDu' touched wa' another Daq the midst vo' the tuq.",
        28: 'ghaH overlaid the cherubim tlhej SuD baS.',
        29: "ghaH carved Hoch the walls vo' the tuq around tlhej carved figures vo' cherubim je palm Sormey je poSmoH flowers, inside je outside.",
        30: "The floor vo' the tuq ghaH overlaid tlhej SuD baS, inside je outside.",
        31: "vaD the entrance vo' the oracle ghaH chenmoHta' doors vo' olive wood: the lintel je lojmIt posts were a fifth part vo' the reD.",
        32: "vaj ghaH chenmoHta' cha' doors vo' olive wood; je ghaH carved Daq chaH carvings vo' cherubim je palm Sormey je poSmoH flowers, je overlaid chaH tlhej SuD baS; je ghaH ngeH the SuD baS Daq the cherubim, je Daq the palm Sormey.",
        33: "vaj je chenmoHta' ghaH vaD the entrance vo' the lalDan qach lojmIt posts vo' olive wood, pa' vo' a fourth part vo' the reD;",
        34: "je cha' doors vo' fir wood: the cha' leaves vo' the wa' lojmIt were folding, je the cha' leaves vo' the latlh lojmIt were folding.",
        35: 'ghaH carved thereon cherubim je palm Sormey je poSmoH flowers; je ghaH overlaid chaH tlhej SuD baS fitted Daq the engraved vum.',
        36: "ghaH chenta' the inner bo'DIj tlhej wej courses vo' pe' nagh, je a course vo' cedar beams.",
        37: "Daq the fourth DIS ghaHta' the foundation vo' the tuq vo' joH'a' laid, Daq the jar Ziv.",
        38: "Daq the eleventh DIS, Daq the jar Bul, nuq ghaH the eighth jar, ghaHta' the tuq finished throughout Hoch its parts, je according Daq Hoch its fashion. vaj ghaHta' ghaH Soch DISmey Daq building 'oH.",
    },
    7: {
        1: "Solomon ghaHta' building Daj ghaj tuq thirteen DISmey, je ghaH finished Hoch Daj tuq.",
        2: "vaD ghaH chenta' the tuq vo' the forest vo' Lebanon; its length ghaHta' wa' vatlh cubits, je its breadth vaghmaH cubits, je its height wejmaH cubits, Daq loS rows vo' cedar pillars, tlhej cedar beams Daq the pillars.",
        3: "'oH ghaHta' covered tlhej cedar Dung Dung the loSmaH- vagh beams, vetlh were Daq the pillars; fifteen Daq a row.",
        4: "pa' were beams Daq wej rows, je window ghaHta' Dung Daq window Daq wej ranks.",
        5: "Hoch the doors je posts were chenmoHta' square tlhej beams: je window ghaHta' Dung Daq window Daq wej ranks.",
        6: "ghaH chenmoHta' the porch vo' pillars; its length ghaHta' vaghmaH cubits, je its breadth wejmaH cubits; je a porch qaSpa' chaH; je pillars je a threshold qaSpa' chaH.",
        7: "ghaH chenmoHta' the porch vo' the quS'a' nuqDaq ghaH ghaHta' Daq noH, 'ach the porch vo' yoj: je 'oH ghaHta' covered tlhej cedar vo' floor Daq floor.",
        8: "Daj tuq nuqDaq ghaH ghaHta' Daq yIn, the latlh bo'DIj within the porch, ghaHta' vo' the rur vum. ghaH chenmoHta' je a tuq vaD Pharaoh's puqbe' ('Iv Solomon ghajta' tlhappu' as be'nal), rur vam porch.",
        9: "Hoch Dochvammey were vo' costly naghmey, 'ach vo' pe' nagh, according Daq juv, sawed tlhej saws, inside je outside, 'ach vo' the foundation Daq the coping, je vaj Daq the outside Daq the Dun bo'DIj.",
        10: "The foundation ghaHta' vo' costly naghmey, 'ach Dun naghmey, naghmey vo' wa'maH cubits, je naghmey vo' eight cubits.",
        11: "Dung were costly naghmey, 'ach pe' nagh, according Daq juv, je cedar wood.",
        12: "The Dun bo'DIj around ghajta' wej courses vo' pe' nagh, je a course vo' cedar beams; rur as the inner bo'DIj vo' the tuq vo' joH'a', je the porch vo' the tuq.",
        13: "joH Solomon ngeHta' je fetched Hiram pa' vo' Tyre.",
        14: "ghaH ghaHta' the puqloD vo' a Heghbe'nal vo' the tuq vo' Naphtali, je Daj vav ghaHta' a loD vo' Tyre, a worker Daq brass; je ghaH ghaHta' tebta' tlhej valtaHghach je yajtaHghach je skill, Daq vum Hoch vum Daq brass. ghaH ghoSta' Daq joH Solomon, je performed Hoch Daj vum.",
        15: "vaD ghaH fashioned the cha' pillars vo' brass, eighteen cubits jen apiece: je a tlhegh vo' cha' wa'maH cubits encircled either vo' chaH about.",
        16: "ghaH chenmoHta' cha' capitals vo' molten brass, Daq cher Daq the tops vo' the pillars: the height vo' the wa' capital ghaHta' vagh cubits, je the height vo' the latlh capital ghaHta' vagh cubits.",
        17: "pa' were nets vo' checker vum, je wreaths vo' chain vum, vaD the capitals nuq were Daq the top vo' the pillars; Soch vaD the wa' capital, je Soch vaD the latlh capital.",
        18: "vaj ghaH chenmoHta' the pillars; je pa' were cha' rows around Daq the wa' network, Daq So' the capitals vetlh were Daq the top vo' the pillars: je vaj ta'ta' ghaH vaD the latlh capital.",
        19: "The capitals vetlh were Daq the top vo' the pillars Daq the porch were vo' lily vum, loS cubits.",
        20: "pa' were capitals Dung je Daq the cha' pillars, close Sum the chor nuq ghaHta' retlh the network: je the pomegranates were cha' vatlh, Daq rows around Daq the latlh capital.",
        21: "ghaH cher Dung the pillars Daq the porch vo' the lalDan qach: je ghaH cher Dung the nIH pillar, je ja' its pong Jachin; je ghaH cher Dung the poS pillar, je ja' its pong Boaz.",
        22: "Daq the top vo' the pillars ghaHta' lily vum: vaj ghaHta' the vum vo' the pillars finished.",
        23: "ghaH chenmoHta' the molten biQ'a' vo' wa'maH cubits vo' brim Daq brim, round Daq compass, je its height ghaHta' vagh cubits; je a tlhegh vo' wejmaH cubits encircled 'oH.",
        24: "bIng its brim around pa' were buds nuq encircled 'oH, vaD wa'maH cubits, encircling the biQ'a': the buds were Daq cha' rows, chuH ghorgh 'oH ghaHta' chuH.",
        25: "'oH Qampu' Daq cha' wa'maH chemvaH, wej leghtaH toward the pemHov nIH, je wej leghtaH toward the pemHov 'et, je wej leghtaH toward the pemHov poS, je wej leghtaH toward the pemHov 'o'; je the biQ'a' ghaHta' cher Daq chaH Dung, je Hoch chaj hinder parts were inward.",
        26: "'oH ghaHta' a handbreadth thick: je its brim ghaHta' worked rur the brim vo' a HIvje', rur the flower vo' a lily: 'oH held cha' SaD baths.",
        27: "ghaH chenmoHta' the wa'maH bases vo' brass; loS cubits ghaHta' the length vo' wa' base, je loS cubits its breadth, je wej cubits its height.",
        28: "The vum vo' the bases ghaHta' Daq vam Da: chaH ghajta' panels; je pa' were panels joj the ledges;",
        29: "je Daq the panels vetlh were joj the ledges were lions, chemvaH, je cherubim; je Daq the ledges pa' ghaHta' a pedestal Dung; je bIng the lions je chemvaH were wreaths vo' hanging vum.",
        30: "Hoch base ghajta' loS bronze wheels, je axles vo' brass; je the loS qamDu' vo' 'oH ghajta' supports: bIng the basin were the supports molten, tlhej wreaths Daq the retlh vo' each.",
        31: "The nujDu' vo' 'oH within the capital je Dung ghaHta' a cubit: je its nujDu' ghaHta' round after the vum vo' a pedestal, a cubit je a bID; je je Daq its nujDu' were engravings, je chaj panels were foursquare, ghobe' round.",
        32: "The loS wheels were underneath the panels; je the axles vo' the wheels were Daq the base: je the height vo' a wheel ghaHta' a cubit je bID a cubit.",
        33: "The vum vo' the wheels ghaHta' rur the vum vo' a chariot wheel: chaj axles, je chaj rims, je chaj spokes, je chaj naves, were Hoch molten.",
        34: "pa' were loS supports Daq the loS corners vo' each base: its supports were vo' the base itself.",
        35: "Daq the top vo' the base ghaHta' pa' a round compass bID a cubit jen; je Daq the top vo' the base its stays je its panels were vo' the rap.",
        36: "Daq the plates vo' its stays, je Daq its panels, ghaH engraved cherubim, lions, je palm Sormey, according Daq the space vo' each, tlhej wreaths Hoch around.",
        37: "After vam Da ghaH chenmoHta' the wa'maH bases: Hoch vo' chaH ghajta' wa' casting, wa' juv, je wa' form.",
        38: "ghaH chenmoHta' wa'maH basins vo' brass: wa' basin contained loSmaH baths; je Hoch basin ghaHta' loS cubits; je Daq Hoch wa' vo' the wa'maH bases wa' basin.",
        39: "ghaH cher the bases, vagh Daq the nIH retlh vo' the tuq, je vagh Daq the poS retlh vo' the tuq: je ghaH cher the biQ'a' Daq the nIH retlh vo' the tuq eastward, toward the pemHov poS.",
        40: "Hiram chenmoHta' the basins, je the shovels, je the basins. vaj Hiram chenmoHta' an pItlh vo' doing Hoch the vum vetlh ghaH worked vaD joH Solomon Daq the tuq vo' joH'a':",
        41: "the cha' pillars, je the cha' bowls vo' the capitals vetlh were Daq the top vo' the pillars; je the cha' networks Daq So' the cha' bowls vo' the capitals vetlh were Daq the top vo' the pillars;",
        42: "je the loS vatlh pomegranates vaD the cha' networks; cha' rows vo' pomegranates vaD each network, Daq So' the cha' bowls vo' the capitals vetlh were Daq the pillars;",
        43: "je the wa'maH bases, je the wa'maH basins Daq the bases;",
        44: "je the wa' biQ'a', je the cha' wa'maH chemvaH bIng the biQ'a';",
        45: "je the pots, je the shovels, je the basins: 'ach Hoch Dochvammey Dujmey, nuq Hiram chenmoHta' vaD joH Solomon, Daq the tuq vo' joH'a', were vo' burnished brass.",
        46: "Daq the plain vo' the Jordan ta'ta' the joH chuH chaH, Daq the clay yav joj Succoth je Zarethan.",
        47: "Solomon poS Hoch the Dujmey unweighed, because chaH were exceeding law': the weight vo' the brass laH ghobe' taH tu'ta' pa'.",
        48: "Solomon chenmoHta' Hoch the Dujmey vetlh were Daq the tuq vo' joH'a': the golden lalDanta' Daq, je the SopDaq whereupon the cha' tIr Soj ghaHta', vo' SuD baS;",
        49: "je the lampstands, vagh Daq the nIH retlh, je vagh Daq the poS, qaSpa' the oracle, vo' pure SuD baS; je the flowers, je the lamps, je the tongs, vo' SuD baS;",
        50: "je the cups, je the snuffers, je the basins, je the spoons, je the qul pans, vo' pure SuD baS; je the hinges, both vaD the doors vo' the inner tuq, the HochHom le' Daq, je vaD the doors vo' the tuq, Daq wit, vo' the lalDan qach, vo' SuD baS.",
        51: "Thus Hoch the vum vetlh joH Solomon worked Daq the tuq vo' joH'a' ghaHta' finished. Solomon qempu' Daq the Dochmey nuq David Daj vav ghajta' dedicated, 'ach the baS chIS, je the SuD baS, je the Dujmey, je lan chaH Daq the treasuries vo' the tuq vo' joH'a'.",
    },
    8: {
        1: "vaj Solomon assembled the quppu' vo' Israel, je Hoch the nachDu' vo' the tuqpu', the joHHom vo' the fathers' juHmey vo' the puqpu' vo' Israel, Daq joH Solomon Daq Jerusalem, Daq qem Dung the Duj vo' the lay' vo' joH'a' pa' vo' the veng vo' David, nuq ghaH Zion.",
        2: "Hoch the loDpu' vo' Israel assembled themselves Daq joH Solomon Daq the 'uQ'a', Daq the jar Ethanim, nuq ghaH the SochDIch jar.",
        3: "Hoch the quppu' vo' Israel ghoSta', je the lalDan vumwI'pu' tlhapta' Dung the Duj.",
        4: "chaH qempu' Dung the Duj vo' joH'a', je the juHHom vo' qep, je Hoch the le' Dujmey vetlh were Daq the juHHom; 'ach Dochvammey ta'ta' the lalDan vumwI'pu' je the Levites qem Dung.",
        5: "joH Solomon je Hoch the tay' ghotpu' vo' Israel, 'Iv were assembled Daq ghaH, were tlhej ghaH qaSpa' the Duj, sacrificing Suy' je cattle, vetlh laH ghobe' taH counted ghobe' toghta' vaD qevmey.",
        6: "The lalDan vumwI'pu' qempu' Daq the Duj vo' the lay' vo' joH'a' Daq its Daq, Daq the oracle vo' the tuq, Daq the HochHom le' Daq, 'ach bIng the telDu' vo' the cherubim.",
        7: "vaD the cherubim ngeH vo' chaj telDu' Dung the Daq vo' the Duj, je the cherubim covered the Duj je its poles Dung.",
        8: "The poles were vaj tIq vetlh the ends vo' the poles were leghpu' vo' the le' Daq qaSpa' the oracle; 'ach chaH were ghobe' leghpu' outside: je pa' chaH 'oH Daq vam jaj.",
        9: "pa' ghaHta' pagh Daq the Duj toD the cha' tables vo' nagh nuq Moses lan pa' Daq Horeb, ghorgh joH'a' chenmoHta' a lay' tlhej the puqpu' vo' Israel, ghorgh chaH ghoSta' pa' vo' the puH vo' Egypt.",
        10: "'oH ghoSta' Daq juS, ghorgh the lalDan vumwI'pu' were ghoS pa' vo' the le' Daq, vetlh the cloud tebta' the tuq vo' joH'a',",
        11: "vaj vetlh the lalDan vumwI'pu' laH ghobe' Qam Daq minister Sum meq vo' the cloud; vaD the batlh vo' joH'a' tebta' the tuq vo' joH'a'.",
        12: "vaj Solomon ja'ta', “joH'a' ghajtaH ja'ta' vetlh ghaH would yIn Daq the thick HurghtaHghach.",
        13: "jIH ghaj DIch chenta' SoH a tuq vo' juH, a Daq vaD SoH Daq yIn Daq reH.”",
        14: "The joH tlhe'ta' Daj qab about, je ghurtaH Hoch the yej vo' Israel: je Hoch the yej vo' Israel Qampu'.",
        15: "ghaH ja'ta', “ghurtaH ghaH joH'a', the joH'a' vo' Israel, 'Iv jatlhta' tlhej Daj nujDu' Daq David lIj vav, je ghajtaH tlhej Daj ghop fulfilled 'oH, ja'ta',",
        16: "‘Since the jaj vetlh jIH qempu' vo' wIj ghotpu Israel pa' vo' Egypt, jIH chose ghobe' veng pa' vo' Hoch the tuqpu' vo' Israel Daq chen a tuq, vetlh wIj pong might taH pa'; 'ach jIH chose David Daq taH Dung wIj ghotpu Israel.'",
        17: "“DaH 'oH ghaHta' Daq the tIq vo' David wIj vav Daq chen a tuq vaD the pong vo' joH'a', the joH'a' vo' Israel.",
        18: "'ach joH'a' ja'ta' Daq David wIj vav, ‘Whereas 'oH ghaHta' Daq lIj tIq Daq chen a tuq vaD wIj pong, SoH ta'ta' QaQ vetlh 'oH ghaHta' Daq lIj tIq.",
        19: "Nevertheless, SoH DIchDaq ghobe' chen the tuq; 'ach lIj puqloD 'Iv DIchDaq ghoS vo' pa' vo' lIj porgh, ghaH DIchDaq chen the tuq vaD wIj pong.'",
        20: "joH'a' ghajtaH established Daj mu' vetlh ghaH jatlhta'; vaD jIH ghaj risen Dung Daq the Daq vo' David wIj vav, je jIH ba' Daq the quS'a' vo' Israel, as joH'a' promised, je ghaj chenta' the tuq vaD the pong vo' joH'a', the joH'a' vo' Israel.",
        21: "pa' jIH ghaj cher a Daq vaD the Duj, Daq nuq ghaH the lay' vo' joH'a', nuq ghaH chenmoHta' tlhej maj vavpu', ghorgh ghaH qempu' chaH pa' vo' the puH vo' Egypt.”",
        22: "Solomon Qampu' qaSpa' the lalDanta' Daq vo' joH'a' Daq the Daq vo' Hoch the yej vo' Israel, je ngeH vo' Daj ghopmey toward chal;",
        23: "je ghaH ja'ta', “joH'a', the joH'a' vo' Israel, pa' ghaH ghobe' joH'a' rur SoH, Daq chal Dung, joq Daq tera' bIng; 'Iv pol lay' je muSHa'taH pung tlhej lIj toy'wI'pu', 'Iv yIt qaSpa' SoH tlhej Hoch chaj tIq;",
        24: "'Iv ghaj polta' tlhej lIj toy'wI' David wIj vav vetlh nuq SoH promised ghaH. HIja', SoH jatlhta' tlhej lIj nujDu', je ghaj fulfilled 'oH tlhej lIj ghop, as 'oH ghaH vam jaj.",
        25: "DaH vaj, may joH'a', the joH'a' vo' Israel, pol tlhej lIj toy'wI' David wIj vav vetlh nuq SoH ghaj promised ghaH, ja'ta', ‘pa' DIchDaq ghobe' fail SoH a loD Daq wIj leghpu' Daq ba' Daq the quS'a' vo' Israel, chugh neH lIj puqpu' tlhap heed Daq chaj way, Daq yIt qaSpa' jIH as SoH ghaj yItta' qaSpa' jIH.'",
        26: "“DaH vaj, joH'a' vo' Israel, please chaw' lIj mu' taH verified, nuq SoH jatlhta' Daq lIj toy'wI' David wIj vav.",
        27: "'ach DichDaq joH'a' Daq very deed yIn Daq the tera'? yIlegh, chal je the chal vo' chal ta'laHbe' contain SoH; chay' 'ar less vam tuq vetlh jIH ghaj chenta'!",
        28: "Yet ghaj respect vaD the tlhobtaHghach vo' lIj toy'wI', je vaD Daj supplication, joH'a' wIj joH'a', Daq 'Ij Daq the SaQ je Daq the tlhobtaHghach nuq lIj toy'wI' prays qaSpa' SoH vam jaj;",
        29: "vetlh lIj mInDu' may taH poSmoH toward vam tuq ram je jaj, 'ach toward the Daq vo' nuq SoH ghaj ja'ta', ‘wIj pong DIchDaq taH pa';' Daq 'Ij Daq the tlhobtaHghach nuq lIj toy'wI' DIchDaq tlhob toward vam Daq.",
        30: "'Ij Daq the supplication vo' lIj toy'wI', je vo' lIj ghotpu Israel, ghorgh chaH DIchDaq tlhob toward vam Daq. HIja', Qoy Daq chal, lIj dwelling Daq; je ghorgh SoH Qoy, forgive.",
        31: "“chugh a loD yemmey Daq Daj jIl, je an oath ghaH laid Daq ghaH Daq cause ghaH Daq swear, je ghaH choltaH je swear qaSpa' lIj lalDanta' Daq Daq vam tuq;",
        32: "vaj Qoy Daq chal, je ta', je noH lIj toy'wI'pu', condemning the mIgh, Daq qem Daj way Daq Daj ghaj nach, je justifying the QaQtaHghach, Daq nob ghaH according Daq Daj QaQtaHghach.",
        33: "“ghorgh lIj ghotpu Israel 'oH struck bIng qaSpa' the jagh, because chaH ghaj yempu' Daq SoH; chugh chaH tlhe' again Daq SoH, je confess lIj pong, je tlhob je chenmoH supplication Daq SoH Daq vam tuq:",
        34: "vaj Qoy Daq chal, je forgive the yem vo' lIj ghotpu Israel, je qem chaH again Daq the puH nuq SoH nobta' Daq chaj vavpu'.",
        35: "“ghorgh the sky ghaH shut Dung, je pa' ghaH ghobe' rain, because chaH ghaj yempu' Daq SoH; chugh chaH tlhob toward vam Daq, je confess lIj pong, je tlhe' vo' chaj yem, ghorgh SoH afflict chaH:",
        36: "vaj Qoy Daq chal, je forgive the yem vo' lIj toy'wI'pu', je vo' lIj ghotpu Israel, ghorgh SoH ghojmoH chaH the QaQ way Daq nuq chaH should yIt; je ngeH rain Daq lIj puH, nuq SoH ghaj nobpu' Daq lIj ghotpu vaD an inheritance.",
        37: "“chugh pa' ghaH famine Daq the puH, chugh pa' ghaH rop'a', chugh pa' ghaH blight, mildew, locust joq caterpillar; chugh chaj jagh besieges chaH Daq the puH vo' chaj vengmey; whatever rop'a', whatever sickness pa' ghaH;",
        38: "whatever tlhobtaHghach je supplication ghaH chenmoHta' Sum vay' loD, joq Sum Hoch lIj ghotpu Israel, 'Iv DIchDaq each Sov the rop'a' vo' Daj ghaj tIq, je ngeH vo' Daj ghopmey toward vam tuq:",
        39: "vaj Qoy Daq chal, lIj dwelling Daq, je forgive, je ta', je render Daq Hoch loD according Daq Hoch Daj Hemey, 'Iv tIq SoH Sov; (vaD SoH, 'ach SoH neH, Sov the tIQDu' vo' Hoch the puqpu' vo' loDpu';)",
        40: "vetlh chaH may taHvIp SoH Hoch the jajmey vetlh chaH yIn Daq the puH nuq SoH nobta' Daq maj vavpu'.",
        41: "“Moreover concerning the foreigner, 'Iv ghaH ghobe' vo' lIj ghotpu Israel, ghorgh ghaH DIchDaq ghoS pa' vo' a Hop Hatlh vaD lIj pong chIch",
        42: "(vaD chaH DIchDaq Qoy vo' lIj Dun pong, je vo' lIj HoS ghop, je vo' lIj outstretched arm); ghorgh ghaH DIchDaq ghoS je tlhob toward vam tuq;",
        43: "Qoy Daq chal, lIj dwelling Daq, je ta' according Daq Hoch vetlh the foreigner calls Daq SoH vaD; vetlh Hoch the ghotpu' vo' the tera' may Sov lIj pong, Daq taHvIp SoH, as ta' lIj ghotpu Israel, je vetlh chaH may Sov vetlh vam tuq nuq jIH ghaj chenta' ghaH ja' Sum lIj pong.",
        44: "“chugh lIj ghotpu jaH pa' Daq may' Daq chaj jagh, Sum whatever way SoH DIchDaq ngeH chaH, je chaH tlhob Daq joH'a' toward the veng nuq SoH ghaj wIvpu', je toward the tuq nuq jIH ghaj chenta' vaD lIj pong;",
        45: 'vaj Qoy Daq chal chaj tlhobtaHghach je chaj supplication, je maintain chaj cause.',
        46: "chugh chaH yem Daq SoH (vaD pa' ghaH ghobe' loD 'Iv ta'be' yem), je SoH 'oH angry tlhej chaH, je toD chaH Daq the jagh, vaj vetlh chaH carry chaH DoH captive Daq the puH vo' the jagh, Hop litHa' joq Sum;",
        47: "yet chugh chaH DIchDaq repent Daq the puH nuqDaq chaH 'oH qengta' captive, je tlhe' again, je chenmoH supplication Daq SoH Daq the puH vo' chaH 'Iv qengta' chaH captive, ja'ta', ‘maH ghaj yempu', je ghaj ta'pu' perversely; maH ghaj dealt wickedly;'",
        48: "chugh chaH chegh Daq SoH tlhej Hoch chaj tIq je tlhej Hoch chaj qa' Daq the puH vo' chaj jaghpu', 'Iv qengta' chaH captive, je tlhob Daq SoH toward chaj puH, nuq SoH nobta' Daq chaj vavpu', the veng nuq SoH ghaj wIvpu', je the tuq nuq jIH ghaj chenta' vaD lIj pong:",
        49: 'vaj Qoy chaj tlhobtaHghach je chaj supplication Daq chal, lIj dwelling Daq, je maintain chaj cause;',
        50: "je forgive lIj ghotpu 'Iv ghaj yempu' Daq SoH, je Hoch chaj transgressions Daq nuq chaH ghaj transgressed Daq SoH; je nob chaH compassion qaSpa' chaH 'Iv qengta' chaH captive, vetlh chaH may ghaj compassion Daq chaH",
        51: "(vaD chaH 'oH lIj ghotpu, je lIj inheritance, nuq SoH qempu' vo' pa' vo' Egypt, vo' the midst vo' the furnace vo' iron);",
        52: "vetlh lIj mInDu' may taH poSmoH Daq the supplication vo' lIj toy'wI', je Daq the supplication vo' lIj ghotpu Israel, Daq 'Ij Daq chaH whenever chaH SaQ Daq SoH.",
        53: "vaD SoH separated chaH vo' among Hoch the ghotpu' vo' the tera', Daq taH lIj inheritance, as SoH jatlhta' Sum Moses lIj toy'wI', ghorgh SoH qempu' maj vavpu' pa' vo' Egypt, joH joH'a'.”",
        54: "'oH ghaHta' vaj, vetlh ghorgh Solomon ghajta' chenmoHta' an pItlh vo' praying Hoch vam tlhobtaHghach je supplication Daq joH'a', ghaH Hu' vo' qaSpa' the lalDanta' Daq vo' joH'a', vo' kneeling Daq Daj knees tlhej Daj ghopmey ngeH vo' toward chal.",
        55: "ghaH Qampu', je ghurtaH Hoch the yej vo' Israel tlhej a loud ghogh, ja'ta',",
        56: "“ghurtaH taH joH'a', 'Iv ghajtaH nobpu' leS Daq Daj ghotpu Israel, according Daq Hoch vetlh ghaH promised. pa' ghajtaH ghobe' failed wa' mu' vo' Hoch Daj QaQ promise, nuq ghaH promised Sum Moses Daj toy'wI'.",
        57: "May joH'a' maj joH'a' taH tlhej maH, as ghaH ghaHta' tlhej maj vavpu'. chaw' ghaH ghobe' mej maH, ghobe' lon maH;",
        58: "vetlh ghaH may incline maj tIQDu' Daq ghaH, Daq yIt Daq Hoch Daj Hemey, je Daq pol Daj ra'ta'ghach mu'mey, je Daj chutmey, je Daj chutmey, nuq ghaH ra'ta' maj vavpu'.",
        59: "chaw' Dochvammey wIj mu'mey, tlhej nuq jIH ghaj chenmoHta' supplication qaSpa' joH'a', taH Sum Daq joH'a' maj joH'a' jaj je ram, vetlh ghaH may maintain the cause vo' Daj toy'wI', je the cause vo' Daj ghotpu Israel, as Hoch jaj DIchDaq require;",
        60: "vetlh Hoch the ghotpu' vo' the tera' may Sov vetlh joH'a', ghaH ghaH joH'a'. pa' ghaH pagh else.",
        61: "“chaw' lIj tIq vaj taH perfect tlhej joH'a' maj joH'a', Daq yIt Daq Daj chutmey, je Daq pol Daj ra'ta'ghach mu'mey, as Daq vam jaj.”",
        62: "The joH, je Hoch Israel tlhej ghaH, nobta' sacrifice qaSpa' joH'a'.",
        63: "Solomon nobta' vaD the sacrifice vo' roj nobmey, nuq ghaH nobta' Daq joH'a', cha' je cha'maH SaD nach vo' cattle, je wa' vatlh cha'maH SaD Suy'. vaj the joH je Hoch the puqpu' vo' Israel dedicated the tuq vo' joH'a'.",
        64: "The rap jaj ta'ta' the joH chenmoH the middle vo' the bo'DIj le' vetlh ghaHta' qaSpa' the tuq vo' joH'a'; vaD pa' ghaH nobta' the meQqu'pu' cha'nob, je the 'uQ cha'nob, je the ror vo' the roj nobmey, because the bronze lalDanta' Daq vetlh ghaHta' qaSpa' joH'a' ghaHta' too mach Daq Hev the meQqu'pu' cha'nob, je the 'uQ cha'nob, je the ror vo' the roj nobmey.",
        65: "vaj Solomon held the 'uQ'a' Daq vetlh poH, je Hoch Israel tlhej ghaH, a Dun yej, vo' the entrance vo' Hamath Daq the brook vo' Egypt, qaSpa' joH'a' maj joH'a', Soch jajmey je Soch jajmey, 'ach fourteen jajmey.",
        66: "Daq the eighth jaj ghaH ngeHta' the ghotpu DoH; je chaH ghurtaH the joH, je mejta' Daq chaj tents joyful je Quchqu' vo' tIq vaD Hoch the QaQ vetlh joH'a' ghajta' shown Daq David Daj toy'wI', je Daq Israel Daj ghotpu.",
    },
    9: {
        1: "'oH qaSta', ghorgh Solomon ghajta' finished the building vo' the tuq vo' joH'a', je the joH tuq, je Hoch Solomon's neH nuq ghaH ghaHta' pleased Daq ta',",
        2: "vetlh joH'a' appeared Daq Solomon the cha'DIch poH, as ghaH ghajta' appeared Daq ghaH Daq Gibeon.",
        3: 'joH\'a\' ja\'ta\' Daq ghaH, " jIH ghaj Qoyta\' lIj tlhobtaHghach je lIj supplication, vetlh SoH ghaj chenmoHta\' qaSpa\' jIH. jIH ghaj chenmoHta\' vam tuq le\', nuq SoH ghaj chenta\', Daq lan wIj pong pa\' reH; je wIj mInDu\' je wIj tIq DIchDaq taH pa\' perpetually.',
        4: "As vaD SoH, chugh SoH DichDaq yIt qaSpa' jIH, as David lIj vav yItta', Daq integrity vo' tIq, je Daq uprightness, Daq ta' according Daq Hoch vetlh jIH ghaj ra'ta' SoH, je DichDaq pol wIj chutmey je wIj chutmey;",
        5: "vaj jIH DichDaq establish the quS'a' vo' lIj kingdom Dung Israel reH, according as jIH promised Daq David lIj vav, ja'ta', ‘pa' DIchDaq ghobe' fail SoH a loD Daq the quS'a' vo' Israel.'",
        6: "'ach chugh SoH tlhe' DoH vo' following jIH, SoH joq lIj puqpu', je ghobe' pol wIj ra'ta'ghach mu'mey je wIj chutmey nuq jIH ghaj cher qaSpa' SoH, 'ach DIchDaq jaH je toy' latlh Qunpu', je lalDan toy' chaH;",
        7: "vaj DichDaq jIH pe' litHa' Israel pa' vo' the puH nuq jIH ghaj nobpu' chaH; je vam tuq, nuq jIH ghaj chenmoHta' le' vaD wIj pong, DichDaq jIH chuH pa' vo' wIj leghpu'; je Israel DIchDaq taH a proverb je a byword among Hoch ghotpu'.",
        8: "'a' vam tuq ghaH vaj jen, yet DIchDaq Hoch 'Iv passes Sum 'oH taH astonished, je DIchDaq hiss; je chaH DIchDaq jatlh, ‘qatlh ghajtaH joH'a' ta'pu' thus Daq vam puH, je Daq vam tuq?'",
        9: "je chaH DIchDaq jang, ‘Because chaH forsook joH'a' chaj joH'a', 'Iv qempu' vo' chaj vavpu' pa' vo' the puH vo' Egypt, je laid 'uch vo' latlh Qunpu', je worshiped chaH, je served chaH. vaj joH'a' ghajtaH qempu' Hoch vam mIghtaHghach Daq chaH.'”",
        10: "'oH qaSta' Daq the pItlh vo' cha'maH DISmey, Daq nuq Solomon ghajta' chenta' the cha' juHmey, the tuq vo' joH'a' je the joH tuq",
        11: "(DaH Hiram the joH vo' Tyre ghajta' furnished Solomon tlhej cedar Sormey je fir Sormey, je tlhej SuD baS, according Daq Hoch Daj neH), vetlh vaj joH Solomon nobta' Hiram cha'maH vengmey Daq the puH vo' Galilee.",
        12: "Hiram ghoSta' pa' vo' Tyre Daq legh the vengmey nuq Solomon ghajta' nobpu' ghaH; je chaH ta'be' please ghaH.",
        13: "ghaH ja'ta', “nuq vengmey 'oH Dochvammey nuq SoH ghaj nobpu' jIH, wIj loDnI'?” ghaH ja' chaH the puH vo' Cabul Daq vam jaj.",
        14: "Hiram ngeHta' Daq the joH wa' vatlh cha'maH talents vo' SuD baS.",
        15: "vam ghaH the meq vo' the levy nuq joH Solomon raised, Daq chen the tuq vo' joH'a', je Daj ghaj tuq, je Millo, je the reD vo' Jerusalem, je Hazor, je Megiddo, je Gezer.",
        16: "Pharaoh joH vo' Egypt ghajta' ghoSta' Dung, je tlhappu' Gezer, je meQqu'pu' 'oH tlhej qul, je Heghta' the Canaanites 'Iv yInta' Daq the veng, je nobpu' 'oH vaD a portion Daq Daj puqbe', Solomon's be'nal.",
        17: "Solomon chenta' Gezer, je Beth Horon the lower,",
        18: 'je Baalath, je Tamar Daq the ngem, Daq the puH,',
        19: "je Hoch the storage vengmey vetlh Solomon ghajta', je the vengmey vaD Daj Dujmey, je the vengmey vaD Daj horsemen, je vetlh nuq Solomon neH Daq chen vaD Daj pleasure Daq Jerusalem, je Daq Lebanon, je Daq Hoch the puH vo' Daj dominion.",
        20: "As vaD Hoch the ghotpu 'Iv were poS vo' the Amorites, the Hittites, the Perizzites, the Hivites, je the Jebusites, 'Iv were ghobe' vo' the puqpu' vo' Israel;",
        21: "chaj puqpu' 'Iv were poS after chaH Daq the puH, 'Iv the puqpu' vo' Israel were ghobe' laH utterly Daq Qaw', vo' chaH ta'ta' Solomon raise a levy vo' bondservants Daq vam jaj.",
        22: "'ach vo' the puqpu' vo' Israel ta'ta' Solomon chenmoH ghobe' bondservants; 'ach chaH were the loDpu' vo' veS, je Daj toy'wI'pu', je Daj joHHom, je Daj HoDpu', je DevwIpu' vo' Daj Dujmey je vo' Daj horsemen.",
        23: "Dochvammey were the pIn officers 'Iv were Dung Solomon's vum, vagh vatlh vaghmaH, 'Iv boghmoH rule Dung the ghotpu 'Iv labored Daq the vum.",
        24: "'ach Pharaoh's puqbe' ghoSta' Dung pa' vo' the veng vo' David Daq Daj tuq nuq Solomon ghajta' chenta' vaD Daj: vaj ta'ta' ghaH chen Millo.",
        25: "wej poHmey a DIS ta'ta' Solomon nob meQqu'pu' nobmey je roj nobmey Daq the lalDanta' Daq nuq ghaH chenta' Daq joH'a', burning He' therewith, Daq the lalDanta' Daq vetlh ghaHta' qaSpa' joH'a'. vaj ghaH finished the tuq.",
        26: "joH Solomon chenmoHta' a navy vo' ships Daq Ezion Geber, nuq ghaH retlh Eloth, Daq the shore vo' the Doq biQ'a' { Note: joq, biQ'a' vo' Reeds }, Daq the puH vo' Edom.",
        27: "Hiram ngeHta' Daq the navy Daj toy'wI'pu', sailors 'Iv ghajta' Sov vo' the biQ'a', tlhej the toy'wI'pu' vo' Solomon.",
        28: "chaH ghoSta' Daq Ophir, je fetched vo' pa' SuD baS, loS vatlh je cha'maH talents, je qempu' 'oH Daq joH Solomon.",
    },
    10: {
        1: "ghorgh the queen vo' Sheba Qoyta' vo' the fame vo' Solomon concerning the pong vo' joH'a', ghaH ghoSta' Daq prove ghaH tlhej hard questions.",
        2: "ghaH ghoSta' Daq Jerusalem tlhej a very Dun train, tlhej camels vetlh boghmoH spices, je very 'ar SuD baS, je precious naghmey; je ghorgh ghaH ghaHta' ghoS Daq Solomon, ghaH talked tlhej ghaH vo' Hoch vetlh ghaHta' Daq Daj tIq.",
        3: "Solomon ja'ta' Daj Hoch Daj questions: pa' ghaHta' ghobe' vay' hidden vo' the joH nuq ghaH ta'be' ja' Daj.",
        4: "ghorgh the queen vo' Sheba ghajta' leghpu' Hoch the valtaHghach vo' Solomon, je the tuq vetlh ghaH ghajta' chenta',",
        5: "je the Soj vo' Daj SopDaq, je the sitting vo' Daj toy'wI'pu', je the attendance vo' Daj ministers, je chaj Sut, je Daj HIvje' qengwI'pu', je Daj ascent Sum nuq ghaH mejta' Dung Daq the tuq vo' joH'a'; pa' ghaHta' ghobe' latlh qa' Daq Daj.",
        6: "ghaH ja'ta' Daq the joH, “'oH ghaHta' a true report vetlh jIH Qoyta' Daq wIj ghaj puH vo' lIj ta'mey, je vo' lIj valtaHghach.",
        7: "However jIH ta'be' Har the mu'mey, until jIH ghoSta', je wIj mInDu' ghajta' leghpu' 'oH. yIlegh, the bID ghaHta' ghobe' ja'ta' jIH! lIj valtaHghach je mIp exceed the fame nuq jIH Qoyta'.",
        8: "Quch 'oH lIj loDpu', Quch 'oH Dochvammey lIj toy'wI'pu', 'Iv Qam continually qaSpa' SoH, 'Iv Qoy lIj valtaHghach.",
        9: "ghurtaH ghaH joH'a' lIj joH'a', 'Iv delighted Daq SoH, Daq cher SoH Daq the quS'a' vo' Israel. Because joH'a' loved Israel reH, vaj chenmoHta' ghaH SoH joH, Daq ta' ruv je QaQtaHghach.”",
        10: "ghaH nobta' the joH wa' vatlh cha'maH talents vo' SuD baS, je vo' spices very Dun store, je precious naghmey. pa' ghoSta' ghobe' latlh such abundance vo' spices as Dochvammey nuq the queen vo' Sheba nobta' Daq joH Solomon.",
        11: "The navy je vo' Hiram, vetlh qempu' SuD baS vo' Ophir, qempu' Daq vo' Ophir Dun plenty vo' almug Sormey je precious naghmey.",
        12: "The joH chenmoHta' vo' the almug Sormey pillars vaD the tuq vo' joH'a', je vaD the joH tuq, harps je je stringed instruments vaD the singers: pa' ghoSta' ghobe' such almug Sormey, ghobe' were leghpu', Daq vam jaj.",
        13: "joH Solomon nobta' Daq the queen vo' Sheba Hoch Daj neH, whatever ghaH tlhobta', je vetlh nuq Solomon nobta' Daj vo' Daj royal bounty. vaj ghaH tlhe'ta', je mejta' Daq Daj ghaj puH, ghaH je Daj toy'wI'pu'.",
        14: "DaH the weight vo' SuD baS vetlh ghoSta' Daq Solomon Daq wa' DIS ghaHta' jav vatlh javmaH- jav talents vo' SuD baS,",
        15: "je vetlh nuq the traders qempu', je the traffic vo' the merchants, je vo' Hoch the joHpu' vo' the DuD ghotpu, je vo' the governors vo' the Hatlh.",
        16: "joH Solomon chenmoHta' cha' vatlh bucklers vo' beaten SuD baS; jav vatlh shekels vo' SuD baS mejta' Daq wa' yoD.",
        17: "ghaH chenmoHta' wej vatlh shields vo' beaten SuD baS; wej minas vo' SuD baS mejta' Daq wa' yoD: je the joH lan chaH Daq the tuq vo' the forest vo' Lebanon.",
        18: "Moreover the joH chenmoHta' a Dun quS'a' vo' ivory, je overlaid 'oH tlhej the finest SuD baS.",
        19: "pa' were jav steps Daq the quS'a', je the top vo' the quS'a' ghaHta' round behind; je pa' were stays Daq either retlh Sum the Daq vo' the seat, je cha' lions standing retlh the stays.",
        20: "cha' wa'maH lions Qampu' pa' Daq the wa' retlh je Daq the latlh Daq the jav steps: pa' ghaHta' pagh rur 'oH chenmoHta' Daq vay' kingdom.",
        21: "Hoch joH Solomon's drinking Dujmey were vo' SuD baS, je Hoch the Dujmey vo' the tuq vo' the forest vo' Lebanon were vo' pure SuD baS: pagh were vo' baS chIS; 'oH ghaHta' pagh accounted vo' Daq the jajmey vo' Solomon.",
        22: "vaD the joH ghajta' Daq biQ'a' a navy vo' Tarshish tlhej the navy vo' Hiram: once Hoch wej DISmey ghoSta' the navy vo' Tarshish, bringing SuD baS, je baS chIS, ivory, je apes, je peacocks.",
        23: "vaj joH Solomon exceeded Hoch the joHpu' vo' the tera' Daq riches je Daq valtaHghach.",
        24: "Hoch the tera' nejta' the Daq vo' Solomon, Daq Qoy Daj valtaHghach, nuq joH'a' ghajta' lan Daq Daj tIq.",
        25: "chaH qempu' Hoch loD Daj tribute, Dujmey vo' baS chIS, je Dujmey vo' SuD baS, je Sut, je armor, je spices, horses, je mules, a rate DIS Sum DIS.",
        26: "Solomon boSta' tay' Dujmey je horsemen: je ghaH ghajta' a SaD je loS vatlh Dujmey, je cha' wa'maH SaD horsemen, vetlh ghaH bestowed Daq the chariot vengmey, je tlhej the joH Daq Jerusalem.",
        27: "The joH chenmoHta' baS chIS Daq taH Daq Jerusalem as naghmey, je cedars chenmoHta' ghaH Daq taH as the sycamore Sormey vetlh 'oH Daq the lowland, vaD abundance.",
        28: "The horses nuq Solomon ghajta' were qempu' pa' vo' Egypt; je the joH merchants Hevta' chaH Daq droves, each drove Daq a price.",
        29: "A chariot ghoSta' Dung je mejta' pa' vo' Egypt vaD jav vatlh shekels vo' baS chIS, je a horse vaD wa' vatlh vaghmaH; je vaj vaD Hoch the joHpu' vo' the Hittites, je vaD the joHpu' vo' Syria, ta'ta' chaH qem chaH pa' Sum chaj means.",
    },
    11: {
        1: "DaH joH Solomon loved law' foreign be'pu', tay' tlhej the puqbe' vo' Pharaoh, be'pu' vo' the Moabites, Ammonites, Edomites, Sidonians, je Hittites;",
        2: "vo' the tuqpu' concerning nuq joH'a' ja'ta' Daq the puqpu' vo' Israel, “SoH DIchDaq ghobe' jaH among chaH, ghobe' DIchDaq chaH ghoS among SoH; vaD DIch chaH DichDaq tlhe' DoH lIj tIq after chaj Qunpu'.” Solomon joined Daq Dochvammey Daq muSHa'.",
        3: "ghaH ghajta' Soch vatlh be'nalpu', princesses, je wej vatlh concubines; je Daj be'nalpu' tlhe'ta' DoH Daj tIq.",
        4: "vaD 'oH qaSta', ghorgh Solomon ghaHta' qan, vetlh Daj be'nalpu' tlhe'ta' DoH Daj tIq after latlh Qunpu'; je Daj tIq ghaHta' ghobe' perfect tlhej joH'a' Daj joH'a', as ghaHta' the tIq vo' David Daj vav.",
        5: "vaD Solomon mejta' after Ashtoreth the goddess vo' the Sidonians, je after Milcom the qabqu'boghghach vo' the Ammonites.",
        6: "Solomon ta'ta' vetlh nuq ghaHta' mIghtaHghach Daq the leghpu' vo' joH'a', je ta'be' jaH fully after joH'a', as ta'ta' David Daj vav.",
        7: "vaj ta'ta' Solomon chen a jen Daq vaD Chemosh the qabqu'boghghach vo' Moab, Daq the HuD vetlh ghaH qaSpa' Jerusalem, je vaD Molech the qabqu'boghghach vo' the puqpu' vo' Ammon.",
        8: "vaj ta'ta' ghaH vaD Hoch Daj foreign be'nalpu', 'Iv meQqu'pu' He' je sacrificed Daq chaj Qunpu'.",
        9: "joH'a' ghaHta' angry tlhej Solomon, because Daj tIq ghaHta' tlhe'ta' DoH vo' joH'a', the joH'a' vo' Israel, 'Iv ghajta' appeared Daq ghaH twice,",
        10: "je ghajta' ra'ta' ghaH concerning vam Doch, vetlh ghaH should ghobe' jaH after latlh Qunpu': 'ach ghaH ta'be' pol vetlh nuq joH'a' ra'ta'.",
        11: "vaj joH'a' ja'ta' Daq Solomon, “Because vam ghaH ta'pu' Sum SoH, je SoH ghaj ghobe' polta' wIj lay' je wIj chutmey, nuq jIH ghaj ra'ta' SoH, jIH DichDaq DIch tear the kingdom vo' SoH, je DichDaq nob 'oH Daq lIj toy'wI'.",
        12: "Notwithstanding jIH DichDaq ghobe' ta' 'oH Daq lIj jajmey, vaD David lIj vav chIch; 'ach jIH DichDaq tear 'oH pa' vo' the ghop vo' lIj puqloD.",
        13: "However jIH DichDaq ghobe' tear DoH Hoch the kingdom; 'ach jIH DichDaq nob wa' tuq Daq lIj puqloD, vaD David wIj toy'wI' chIch, je vaD Jerusalem's chIch nuq jIH ghaj wIvpu'.”",
        14: "joH'a' raised Dung an jagh Daq Solomon, Hadad the Edomite: ghaH ghaHta' vo' the joH tIr Daq Edom.",
        15: "vaD 'oH qaSta', ghorgh David ghaHta' Daq Edom, je Joab the HoD vo' the army ghaHta' ghoSta' Dung Daq bury the Heghta', je ghajta' struck Hoch male Daq Edom",
        16: "(vaD Joab je Hoch Israel remained pa' jav months, until ghaH ghajta' pe' litHa' Hoch male Daq Edom);",
        17: "vetlh Hadad Haw'ta', ghaH je Dich Edomites vo' Daj vav toy'wI'pu' tlhej ghaH, Daq jaH Daq Egypt, Hadad taH yet a mach puq.",
        18: "chaH Hu' pa' vo' Midian, je ghoSta' Daq Paran; je chaH tlhapta' loDpu' tlhej chaH pa' vo' Paran, je chaH ghoSta' Daq Egypt, Daq Pharaoh joH vo' Egypt, 'Iv nobta' ghaH a tuq, je wIv ghaH Soj, je nobta' ghaH puH.",
        19: "Hadad tu'ta' Dun favor Daq the leghpu' vo' Pharaoh, vaj vetlh ghaH nobta' ghaH as be'nal the sister vo' Daj ghaj be'nal, the sister vo' Tahpenes the queen.",
        20: "The sister vo' Tahpenes boghmoH ghaH Genubath Daj puqloD, 'Iv Tahpenes weaned Daq Pharaoh's tuq; je Genubath ghaHta' Daq Pharaoh's tuq among the puqloDpu' vo' Pharaoh.",
        21: "ghorgh Hadad Qoyta' Daq Egypt vetlh David Qongta' tlhej Daj vavpu', je vetlh Joab the HoD vo' the army ghaHta' Heghpu', Hadad ja'ta' Daq Pharaoh, “chaw' jIH mej, vetlh jIH may jaH Daq wIj ghaj Hatlh.”",
        22: "vaj Pharaoh ja'ta' Daq ghaH, “'ach nuq ghaj SoH lacked tlhej jIH, vetlh yIlegh, SoH nej Daq jaH Daq lIj ghaj Hatlh?” ghaH jangta', “pagh, however neH chaw' jIH mej.”",
        23: "joH'a' raised Dung another jagh Daq ghaH, Rezon the puqloD vo' Eliada, 'Iv ghajta' Haw'ta' vo' Daj joH Hadadezer joH vo' Zobah.",
        24: "ghaH boSta' loDpu' Daq ghaH, je mojta' HoD Dung a troop, ghorgh David HoHta' chaH vo' Zobah: je chaH mejta' Daq Damascus, je yInta' therein, je che'ta' Daq Damascus.",
        25: "ghaH ghaHta' an jagh Daq Israel Hoch the jajmey vo' Solomon, je the mischief vetlh Hadad ta'ta': je ghaH abhorred Israel, je che'ta' Dung Syria.",
        26: "Jeroboam the puqloD vo' Nebat, an Ephraimite vo' Zeredah, a toy'wI' vo' Solomon, 'Iv mother's pong ghaHta' Zeruah, a Heghbe'nal, ghaH je qengta' Dung Daj ghop Daq the joH.",
        27: "vam ghaHta' the meq qatlh ghaH qengta' Dung Daj ghop Daq the joH: Solomon chenta' Millo, je repaired the breach vo' the veng vo' David Daj vav.",
        28: "The loD Jeroboam ghaHta' a HoS loD vo' valor; je Solomon leghta' the Qup loD vetlh ghaH ghaHta' industrious, je ghaH lan ghaH Daq yov vo' Hoch the labor vo' the tuq vo' Joseph.",
        29: "'oH qaSta' Daq vetlh poH, ghorgh Jeroboam mejta' pa' vo' Jerusalem, vetlh the leghwI'pu' Ahijah the Shilonite tu'ta' ghaH Daq the way; DaH Ahijah ghajta' clad himself tlhej a chu' garment; je chaH cha' were mob Daq the yotlh.",
        30: "Ahijah laid 'uch vo' the chu' garment vetlh ghaHta' Daq ghaH, je tore 'oH Daq cha' wa'maH pieces.",
        31: "ghaH ja'ta' Daq Jeroboam, “tlhap wa'maH pieces; vaD thus jatlhtaH joH'a', the joH'a' vo' Israel, ‘yIlegh, jIH DichDaq tear the kingdom pa' vo' the ghop vo' Solomon, je DichDaq nob wa'maH tuqpu' Daq SoH",
        32: "('ach ghaH DIchDaq ghaj wa' tuq, vaD wIj toy'wI' David's chIch je vaD Jerusalem's chIch, the veng nuq jIH ghaj wIvpu' pa' vo' Hoch the tuqpu' vo' Israel);",
        33: "because vetlh chaH ghaj lonta' jIH, je ghaj worshiped Ashtoreth the goddess vo' the Sidonians, Chemosh the joH'a' vo' Moab, je Milcom the joH'a' vo' the puqpu' vo' Ammon. chaH ghaj ghobe' yItta' Daq wIj Hemey, Daq ta' vetlh nuq ghaH nIH Daq wIj mInDu', je Daq pol wIj chutmey je wIj chutmey, as David Daj vav ta'ta'.",
        34: "“‘However jIH DichDaq ghobe' tlhap the Hoch kingdom pa' vo' Daj ghop; 'ach jIH DichDaq chenmoH ghaH joHHom Hoch the jajmey vo' Daj yIn, vaD David wIj toy'wI' chIch 'Iv jIH chose, 'Iv polta' wIj ra'ta'ghach mu'mey je wIj chutmey;",
        35: "'ach jIH DichDaq tlhap the kingdom pa' vo' Daj son's ghop, je DichDaq nob 'oH Daq SoH, 'ach wa'maH tuqpu'.",
        36: "Daq Daj puqloD DichDaq jIH nob wa' tuq, vetlh David wIj toy'wI' may ghaj a lamp always qaSpa' jIH Daq Jerusalem, the veng nuq jIH ghaj wIvpu' jIH Daq lan wIj pong pa'.",
        37: "jIH DichDaq tlhap SoH, je SoH DIchDaq che' according Daq Hoch vetlh lIj qa' desires, je DIchDaq taH joH Dung Israel.",
        38: "'oH DIchDaq taH, chugh SoH DichDaq 'Ij Daq Hoch vetlh jIH ra'ta'ghach mu'mey SoH, je DichDaq yIt Daq wIj Hemey, je ta' vetlh nuq ghaH nIH Daq wIj mInDu', Daq pol wIj chutmey je wIj ra'ta'ghach mu'mey, as David wIj toy'wI' ta'ta'; vetlh jIH DichDaq taH tlhej SoH, je DichDaq chen SoH a sure tuq, as jIH chenta' vaD David, je DichDaq nob Israel Daq SoH.",
        39: "jIH DichDaq vaD vam afflict the tIr vo' David, 'ach ghobe' reH.'”",
        40: "Solomon nejta' vaj Daq HoH Jeroboam; 'ach Jeroboam Hu', je Haw'ta' Daq Egypt, Daq Shishak joH vo' Egypt, je ghaHta' Daq Egypt until the Hegh vo' Solomon.",
        41: "DaH the leS vo' the ta'mey vo' Solomon, je Hoch vetlh ghaH ta'ta', je Daj valtaHghach, aren't chaH ghItlhta' Daq the paq vo' the ta'mey vo' Solomon?",
        42: "The poH vetlh Solomon che'ta' Daq Jerusalem Dung Hoch Israel ghaHta' loSmaH DISmey.",
        43: "Solomon Qongta' tlhej Daj vavpu', je ghaHta' buried Daq the veng vo' David Daj vav: je Rehoboam Daj puqloD che'ta' Daq Daj Daq.",
    },
    12: {
        1: "Rehoboam mejta' Daq Shechem: vaD Hoch Israel were ghoS Daq Shechem Daq chenmoH ghaH joH.",
        2: "'oH qaSta', ghorgh Jeroboam the puqloD vo' Nebat Qoyta' vo' 'oH (vaD ghaH ghaHta' yet Daq Egypt, nuqDaq ghaH ghajta' Haw'ta' vo' the Daq vo' joH Solomon, je Jeroboam yInta' Daq Egypt,",
        3: "je chaH ngeHta' je ja' ghaH), vetlh Jeroboam je Hoch the yej vo' Israel ghoSta', je jatlhta' Daq Rehoboam, ja'ta',",
        4: "“lIj vav chenmoHta' maj yoke grievous: DaH vaj chenmoH SoH the grievous toy'taHghach vo' lIj vav, je Daj 'ugh yoke nuq ghaH lan Daq maH, lighter, je maH DichDaq toy' SoH.”",
        5: "ghaH ja'ta' Daq chaH, “mej vaD wej jajmey, vaj ghoS DoH Daq jIH.” The ghotpu departed.",
        6: "joH Rehoboam tlhapta' qeS tlhej the qan loDpu', 'Iv ghajta' Qampu' qaSpa' Solomon Daj vav qaStaHvIS ghaH yet yInta', ja'ta', “nuq qeS ta' SoH nob jIH Daq chegh jang Daq vam ghotpu?”",
        7: "chaH jatlhta' Daq ghaH, ja'ta', “chugh SoH DichDaq taH a toy'wI' Daq vam ghotpu vam jaj, je DichDaq toy' chaH, je jang chaH, je jatlh QaQ mu'mey Daq chaH, vaj chaH DichDaq taH lIj toy'wI'pu' reH.”",
        8: "'ach ghaH forsook the qeS vo' the qan loDpu' nuq chaH ghajta' nobpu' ghaH, je tlhapta' qeS tlhej the Qup loDpu' 'Iv ghajta' grown Dung tlhej ghaH, 'Iv Qampu' qaSpa' ghaH.",
        9: "ghaH ja'ta' Daq chaH, “nuq qeS ta' SoH nob, vetlh maH may chegh jang Daq vam ghotpu, 'Iv ghaj jatlhpu' Daq jIH, ja'ta', ‘chenmoH the yoke vetlh lIj vav ta'ta' lan Daq maH lighter?'”",
        10: "The Qup loDpu' 'Iv ghajta' grown Dung tlhej ghaH jatlhta' Daq ghaH, ja'ta', “Thus SoH DIchDaq ja' vam ghotpu 'Iv jatlhta' Daq SoH, ja'ta', ‘lIj vav chenmoHta' maj yoke 'ugh, 'ach chenmoH 'oH lighter Daq maH;' SoH DIchDaq jatlh Daq chaH, ‘wIj mach finger ghaH thicker than wIj vav waist.",
        11: "DaH whereas wIj vav burdened SoH tlhej a 'ugh yoke, jIH DichDaq chel Daq lIj yoke: wIj vav chastised SoH tlhej whips, 'ach jIH DichDaq chastise SoH tlhej scorpions.'”",
        12: "vaj Jeroboam je Hoch the ghotpu ghoSta' Daq Rehoboam the wejDIch jaj, as the joH tlhobta', ja'ta', “ghoS Daq jIH again the wejDIch jaj.”",
        13: "The joH jangta' the ghotpu roughly, je forsook the qeS vo' the qan loDpu' nuq chaH ghajta' nobpu' ghaH,",
        14: "je jatlhta' Daq chaH according Daq the qeS vo' the Qup loDpu', ja'ta', “wIj vav chenmoHta' lIj yoke 'ugh, 'ach jIH DichDaq chel Daq lIj yoke. wIj vav chastised SoH tlhej whips, 'ach jIH DichDaq chastise SoH tlhej scorpions.”",
        15: "vaj the joH ta'be' 'Ij Daq the ghotpu; vaD 'oH ghaHta' a Doch qempu' about vo' joH'a', vetlh ghaH might establish Daj mu', nuq joH'a' jatlhta' Sum Ahijah the Shilonite Daq Jeroboam the puqloD vo' Nebat.",
        16: "ghorgh Hoch Israel leghta' vetlh the joH ta'be' 'Ij Daq chaH, the ghotpu jangta' the joH, ja'ta', “nuq portion ghaj maH Daq David? ghobe' ta' maH ghaj an inheritance Daq the puqloD vo' Jesse. Daq lIj tents, Israel! DaH legh Daq lIj ghaj tuq, David.” vaj Israel departed Daq chaj tents.",
        17: "'ach as vaD the puqpu' vo' Israel 'Iv yInta' Daq the vengmey vo' Judah, Rehoboam che'ta' Dung chaH.",
        18: "vaj joH Rehoboam ngeHta' Adoram, 'Iv ghaHta' Dung the loDpu' subject Daq forced labor; je Hoch Israel stoned ghaH Daq Hegh tlhej naghmey. joH Rehoboam chenmoHta' speed Daq tlhap ghaH Dung Daq Daj chariot, Daq Haw' Daq Jerusalem.",
        19: "vaj Israel lotlhpu' Daq the tuq vo' David Daq vam jaj.",
        20: "'oH qaSta', ghorgh Hoch Israel Qoyta' vetlh Jeroboam ghaHta' cheghta', vetlh chaH ngeHta' je ja' ghaH Daq the tay' ghotpu', je chenmoHta' ghaH joH Dung Hoch Israel: pa' ghaHta' pagh 'Iv tlha'ta' the tuq vo' David, 'ach the tuq vo' Judah neH.",
        21: "ghorgh Rehoboam ghaHta' ghoS Daq Jerusalem, ghaH assembled Hoch the tuq vo' Judah, je the tuq vo' Benjamin, a vatlh je eighty SaD wIvpu' loDpu', 'Iv were warriors, Daq Suv Daq the tuq vo' Israel, Daq qem the kingdom again Daq Rehoboam the puqloD vo' Solomon.",
        22: "'ach the mu' vo' joH'a' ghoSta' Daq Shemaiah the loD vo' joH'a', ja'ta',",
        23: "“jatlh Daq Rehoboam the puqloD vo' Solomon, joH vo' Judah, je Daq Hoch the tuq vo' Judah je Benjamin, je Daq the leS vo' the ghotpu, ja'ta',",
        24: "‘Thus jatlhtaH joH'a', “SoH DIchDaq ghobe' jaH Dung, ghobe' Suv Daq lIj loDnI'pu', the puqpu' vo' Israel. Hoch chegh Daq Daj tuq; vaD vam Doch ghaH vo' jIH.”'” vaj chaH listened Daq the mu' vo' joH'a', je cheghta' je mejta' chaj way, according Daq the mu' vo' joH'a'.",
        25: "vaj Jeroboam chenta' Shechem Daq the HuD Hatlh vo' Ephraim, je yInta' Daq 'oH; je ghaH mejta' pa' vo' pa', je chenta' Penuel.",
        26: "Jeroboam ja'ta' Daq Daj tIq, “DaH the kingdom DichDaq chegh Daq the tuq vo' David.",
        27: "chugh vam ghotpu goes Dung Daq nob nobmey Daq the tuq vo' joH'a' Daq Jerusalem, vaj the tIq vo' vam ghotpu DichDaq tlhe' again Daq chaj joH, 'ach Daq Rehoboam joH vo' Judah; je chaH DichDaq HoH jIH, je chegh Daq Rehoboam joH vo' Judah.”",
        28: "Whereupon the joH tlhapta' qeS, je chenmoHta' cha' calves vo' SuD baS; je ghaH ja'ta' Daq chaH, “'oH ghaH too 'ar vaD SoH Daq jaH Dung Daq Jerusalem. legh je legh lIj Qunpu', Israel, nuq qempu' SoH Dung pa' vo' the puH vo' Egypt!”",
        29: "ghaH cher the wa' Daq Bethel, je the latlh lan ghaH Daq Dan.",
        30: "vam Doch mojta' a yem; vaD the ghotpu mejta' Daq lalDan toy' qaSpa' the wa', 'ach Daq Dan.",
        31: "ghaH chenmoHta' juHmey vo' jen Daqmey, je chenmoHta' lalDan vumwI'pu' vo' among Hoch the ghotpu, 'Iv were ghobe' vo' the puqloDpu' vo' Levi.",
        32: "Jeroboam ordained a 'uQ'a' Daq the eighth jar, Daq the fifteenth jaj vo' the jar, rur the 'uQ'a' vetlh ghaH Daq Judah, je ghaH mejta' Dung Daq the lalDanta' Daq; vaj ta'ta' ghaH Daq Bethel, sacrificing Daq the calves vetlh ghaH ghajta' chenmoHta': je ghaH placed Daq Bethel the lalDan vumwI'pu' vo' the jen Daqmey vetlh ghaH ghajta' chenmoHta'.",
        33: "ghaH mejta' Dung Daq the lalDanta' Daq nuq ghaH ghajta' chenmoHta' Daq Bethel Daq the fifteenth jaj Daq the eighth jar, 'ach Daq the jar nuq ghaH ghajta' devised vo' Daj ghaj tIq: je ghaH ordained a 'uQ'a' vaD the puqpu' vo' Israel, je mejta' Dung Daq the lalDanta' Daq, Daq meQ He'.",
    },
    13: {
        1: "yIlegh, pa' ghoSta' a loD vo' joH'a' pa' vo' Judah Sum the mu' vo' joH'a' Daq Beth El: je Jeroboam ghaHta' standing Sum the lalDanta' Daq Daq meQ He'.",
        2: "ghaH SaQta' Daq the lalDanta' Daq Sum the mu' vo' joH'a', je ja'ta', “lalDanta' Daq, lalDanta' Daq, thus jatlhtaH joH'a': ‘yIlegh, a puqloD DIchDaq taH bogh Daq the tuq vo' David, Josiah Sum pong. Daq SoH ghaH DIchDaq sacrifice the lalDan vumwI'pu' vo' the jen Daqmey 'Iv meQ He' Daq SoH, je chaH DichDaq meQ men's HomDu' Daq SoH.'”",
        3: "ghaH nobta' a sign the rap jaj, ja'ta', “vam ghaH the sign nuq joH'a' ghajtaH jatlhpu': yIlegh, the lalDanta' Daq DichDaq taH split apart, je the ashes vetlh 'oH Daq 'oH DichDaq taH poured pa'.”",
        4: "'oH qaSta', ghorgh the joH Qoyta' the ja'ta' vo' the loD vo' joH'a', nuq ghaH SaQta' Daq the lalDanta' Daq Daq Bethel, vetlh Jeroboam lan pa' Daj ghop vo' the lalDanta' Daq, ja'ta', “Seize ghaH!” Daj ghop, nuq ghaH lan pa' Daq ghaH, dried Dung, vaj vetlh ghaH laH ghobe' draw 'oH DoH again Daq himself.",
        5: "The lalDanta' Daq je ghaHta' split apart, je the ashes poured pa' vo' the lalDanta' Daq, according Daq the sign nuq the loD vo' joH'a' ghajta' nobpu' Sum the mu' vo' joH'a'.",
        6: "The joH jangta' the loD vo' joH'a', “DaH entreat the favor vo' joH'a' lIj joH'a', je tlhob vaD jIH, vetlh wIj ghop may taH restored jIH again.” The loD vo' joH'a' entreated joH'a', je the joH ghop ghaHta' restored ghaH again, je mojta' as 'oH ghaHta' qaSpa'.",
        7: "The joH ja'ta' Daq the loD vo' joH'a', “ghoS home tlhej jIH, je refresh SoH'egh, je jIH DichDaq nob SoH a pop.”",
        8: "The loD vo' joH'a' ja'ta' Daq the joH, “'ach chugh SoH nobta' jIH bID vo' lIj tuq, jIH would ghobe' jaH Daq tlhej SoH, ghobe' would jIH Sop tIr Soj ghobe' tlhutlh bIQ Daq vam Daq;",
        9: "vaD vaj ghaHta' 'oH ra'ta' jIH Sum the mu' vo' joH'a', ja'ta', ‘SoH DIchDaq Sop ghobe' tIr Soj, ghobe' tlhutlh bIQ, ghobe' chegh Sum the way vetlh SoH ghoSta'.'”",
        10: "vaj ghaH mejta' another way, je ta'be' chegh Sum the way vetlh ghaH ghoSta' Daq Bethel.",
        11: "DaH pa' yInta' an qan leghwI'pu' Daq Bethel; je wa' vo' Daj puqloDpu' ghoSta' je ja'ta' ghaH Hoch the vum vetlh the loD vo' joH'a' ghajta' ta'pu' vetlh jaj Daq Bethel. chaH je ja'ta' chaj vav the mu'mey nuq ghaH ghajta' jatlhpu' Daq the joH.",
        12: "chaj vav ja'ta' Daq chaH, “nuq way ta'ta' ghaH jaH?” DaH Daj puqloDpu' ghajta' leghpu' nuq way the loD vo' joH'a' mejta', 'Iv ghoSta' vo' Judah.",
        13: "ghaH ja'ta' Daq Daj puqloDpu', “Saddle the SarghHom vaD jIH.” vaj chaH saddled the SarghHom vaD ghaH; je ghaH rode Daq 'oH.",
        14: "ghaH mejta' after the loD vo' joH'a', je tu'ta' ghaH sitting bIng an Sor'a'. ghaH ja'ta' Daq ghaH, “'oH SoH the loD vo' joH'a' 'Iv ghoSta' vo' Judah?” ghaH ja'ta', “jIH 'oH.”",
        15: "vaj ghaH ja'ta' Daq ghaH, “ghoS home tlhej jIH, je Sop tIr Soj.”",
        16: "ghaH ja'ta', “jIH may ghobe' chegh tlhej SoH, ghobe' jaH Daq tlhej SoH; ghobe' DichDaq jIH Sop tIr Soj ghobe' tlhutlh bIQ tlhej SoH Daq vam Daq.",
        17: "vaD 'oH ghaHta' ja'ta' Daq jIH Sum the mu' vo' joH'a', ‘SoH DIchDaq Sop ghobe' tIr Soj ghobe' tlhutlh bIQ pa', ghobe' tlhe' again Daq jaH Sum the way vetlh SoH ghoSta'.'”",
        18: "ghaH ja'ta' Daq ghaH, “jIH je 'oH a leghwI'pu' as SoH 'oH; je an Duy jatlhta' Daq jIH Sum the mu' vo' joH'a', ja'ta', ‘qem ghaH DoH tlhej SoH Daq lIj tuq, vetlh ghaH may Sop tIr Soj je tlhutlh bIQ.'” ghaH lied Daq ghaH.",
        19: "vaj ghaH mejta' DoH tlhej ghaH, je ate tIr Soj Daq Daj tuq, je drank bIQ.",
        20: "'oH qaSta', as chaH ba'ta' Daq the SopDaq, vetlh the mu' vo' joH'a' ghoSta' Daq the leghwI'pu' 'Iv qempu' ghaH DoH;",
        21: "je ghaH SaQta' Daq the loD vo' joH'a' 'Iv ghoSta' vo' Judah, ja'ta', “Thus jatlhtaH joH'a', ‘Because SoH ghaj taH disobedient Daq the nujDu' vo' joH'a', je ghaj ghobe' polta' the ra'ta'ghach mu' nuq joH'a' lIj joH'a' ra'ta' SoH,",
        22: "'ach ghoSta' DoH, je ghaj eaten tIr Soj je drunk bIQ Daq the Daq vo' nuq ghaH ja'ta' Daq SoH, “Sop ghobe' tIr Soj, je tlhutlh ghobe' bIQ;” lIj porgh DIchDaq ghobe' ghoS Daq the tomb vo' lIj vavpu'.'”",
        23: "'oH qaSta', after ghaH ghajta' eaten tIr Soj, je after ghaH ghajta' drunk, vetlh ghaH saddled the SarghHom vaD the leghwI'pu' 'Iv ghaH ghajta' qempu' DoH.",
        24: "ghorgh ghaH ghajta' ghoSta', a HaDI'baH met ghaH Sum the way, je HoHta' ghaH. Daj porgh ghaHta' chuH Daq the way, je the SarghHom Qampu' Sum 'oH. The HaDI'baH je Qampu' Sum the porgh.",
        25: "yIlegh, loDpu' juSta' Sum, je leghta' the porgh chuH Daq the way, je the HaDI'baH standing Sum the porgh; je chaH ghoSta' je ja'ta' 'oH Daq the veng nuqDaq the qan leghwI'pu' yInta'.",
        26: "ghorgh the leghwI'pu' 'Iv qempu' ghaH DoH vo' the way Qoyta' vo' 'oH, ghaH ja'ta', “'oH ghaH the loD vo' joH'a' 'Iv ghaHta' disobedient Daq the nujDu' vo' joH'a'. vaj joH'a' ghajtaH toDta' ghaH Daq the HaDI'baH, nuq ghajtaH mauled ghaH je Heghta' ghaH, according Daq the mu' vo' joH'a', nuq ghaH jatlhta' Daq ghaH.”",
        27: "ghaH jatlhta' Daq Daj puqloDpu', ja'ta', “Saddle the SarghHom vaD jIH.” chaH saddled 'oH.",
        28: "ghaH mejta' je tu'ta' Daj porgh chuH Daq the way, je the SarghHom je the HaDI'baH standing Sum the porgh. The HaDI'baH ghajta' ghobe' eaten the porgh, ghobe' mauled the SarghHom.",
        29: "The leghwI'pu' tlhapta' Dung the porgh vo' the loD vo' joH'a', je laid 'oH Daq the SarghHom, je qempu' 'oH DoH. ghaH ghoSta' Daq the veng vo' the qan leghwI'pu' Daq mourn, je Daq bury ghaH.",
        30: "ghaH laid Daj porgh Daq Daj ghaj grave; je chaH mourned Dung ghaH, ja'ta', “Alas, wIj loDnI'!”",
        31: "'oH qaSta', after ghaH ghajta' buried ghaH, vetlh ghaH jatlhta' Daq Daj puqloDpu', ja'ta', “ghorgh jIH 'oH Heghpu', vaj bury jIH Daq the tomb Daq nuq the loD vo' joH'a' ghaH buried. Lay wIj HomDu' retlh Daj HomDu'.",
        32: "vaD the ja'ta' nuq ghaH SaQta' Sum the mu' vo' joH'a' Daq the lalDanta' Daq Daq Bethel, je Daq Hoch the juHmey vo' the jen Daqmey nuq 'oH Daq the vengmey vo' Samaria, DichDaq DIch qaS.”",
        33: "After vam Doch Jeroboam ta'be' chegh vo' Daj mIghtaHghach way, 'ach again chenmoHta' lalDan vumwI'pu' vo' the jen Daqmey vo' among Hoch the ghotpu. 'Iv wanted Daq, ghaH consecrated ghaH, vetlh pa' might taH lalDan vumwI'pu' vo' the jen Daqmey.",
        34: "vam Doch mojta' yem Daq the tuq vo' Jeroboam, 'ach Daq pe' 'oH litHa', je Daq Qaw' 'oH vo' litHa' the surface vo' the tera'.",
    },
    14: {
        1: "Daq vetlh poH Abijah the puqloD vo' Jeroboam pumta' rop.",
        2: "Jeroboam ja'ta' Daq Daj taH'nal, “Please tlhap Dung je disguise SoH'egh, vetlh SoH won't be recognized as the be'nal vo' Jeroboam. jaH Daq Shiloh. yIlegh, pa' ghaH Ahijah the leghwI'pu', 'Iv jatlhta' concerning jIH vetlh jIH should taH joH Dung vam ghotpu.",
        3: "tlhap tlhej SoH wa'maH loaves, je cakes, je a jar vo' honey, je jaH Daq ghaH. ghaH DichDaq ja' SoH nuq DichDaq moj vo' the puq.”",
        4: "Jeroboam's be'nal ta'ta' vaj, je Hu', je mejta' Daq Shiloh, je ghoSta' Daq the tuq vo' Ahijah. DaH Ahijah laH ghobe' legh; vaD Daj mInDu' were cher Sum meq vo' Daj age.",
        5: "joH'a' ja'ta' Daq Ahijah, “yIlegh, the be'nal vo' Jeroboam choltaH Daq inquire vo' SoH concerning Daj puqloD; vaD ghaH ghaH rop. Thus je thus SoH DIchDaq ja' Daj; vaD 'oH DichDaq taH, ghorgh ghaH choltaH Daq, vetlh ghaH DichDaq pretend Daq taH another be'.”",
        6: "'oH ghaHta' vaj, ghorgh Ahijah Qoyta' the wab vo' Daj qamDu', as ghaH ghoSta' Daq Daq the lojmIt, vetlh ghaH ja'ta', “ghoS Daq, SoH be'nal vo' Jeroboam! qatlh ta' SoH pretend Daq taH another? vaD jIH 'oH ngeHta' Daq SoH tlhej 'ugh news.",
        7: "jaH, ja' Jeroboam, ‘Thus jatlhtaH joH'a', the joH'a' vo' Israel: “Because jIH exalted SoH vo' among the ghotpu, je chenmoHta' SoH joHHom Dung wIj ghotpu Israel,",
        8: "je tore the kingdom DoH vo' the tuq vo' David, je nobta' 'oH SoH; je yet SoH ghaj ghobe' taH as wIj toy'wI' David, 'Iv polta' wIj ra'ta'ghach mu'mey, je 'Iv tlha'ta' jIH tlhej Hoch Daj tIq, Daq ta' vetlh neH nuq ghaHta' nIH Daq wIj mInDu',",
        9: "'ach ghaj ta'pu' mIghtaHghach Dung Hoch 'Iv were qaSpa' SoH, je ghaj ghoSta' je chenmoHta' SoH latlh Qunpu', je molten images, Daq provoke jIH Daq QeH, je ghaj chuH jIH behind lIj DoH:",
        10: "vaj, yIlegh, jIH DichDaq qem mIghtaHghach Daq the tuq vo' Jeroboam, je DichDaq pe' litHa' vo' Jeroboam Hoch 'Iv urinates Daq a reD, { Note: joq, male } ghaH 'Iv ghaH shut Dung je ghaH 'Iv ghaH poS Daq large Daq Israel, je DichDaq utterly sweep DoH the tuq vo' Jeroboam, as a loD sweeps DoH dung, until 'oH ghaH Hoch ghoSta'.",
        11: "ghaH 'Iv dies vo' Jeroboam Daq the veng DIchDaq the dogs Sop; je ghaH 'Iv dies Daq the yotlh DIchDaq the toQmey vo' the sky Sop: vaD joH'a' ghajtaH jatlhpu' 'oH.”'",
        12: "Hu' vaj, je jaH Daq lIj tuq. ghorgh lIj qamDu' 'el Daq the veng, the puq DIchDaq Hegh.",
        13: "Hoch Israel DIchDaq mourn vaD ghaH, je bury ghaH; vaD ghaH neH vo' Jeroboam DIchDaq ghoS Daq the grave, because Daq ghaH pa' ghaH tu'ta' 'op QaQ Doch toward joH'a', the joH'a' vo' Israel, Daq the tuq vo' Jeroboam.",
        14: "Moreover joH'a' DichDaq raise ghaH Dung a joH Dung Israel, 'Iv DIchDaq pe' litHa' the tuq vo' Jeroboam. vam ghaH jaj! nuq? 'ach DaH.",
        15: "vaD joH'a' DichDaq mup Israel, as a reed ghaH shaken Daq the bIQ; je ghaH DichDaq root Dung Israel pa' vo' vam QaQ puH nuq ghaH nobta' Daq chaj vavpu', je DichDaq scatter chaH beyond the bIQtIQ, because chaH ghaj chenmoHta' chaj Asherim, provoking joH'a' Daq QeH.",
        16: "ghaH DichDaq nob Israel Dung because vo' the yemmey vo' Jeroboam, nuq ghaH ghajtaH yempu', je tlhej nuq ghaH ghajtaH chenmoHta' Israel Daq yem.”",
        17: "Jeroboam's be'nal Hu', je departed, je ghoSta' Daq Tirzah. As ghaH ghoSta' Daq the threshold vo' the tuq, the puq Heghta'.",
        18: "Hoch Israel buried ghaH, je mourned vaD ghaH, according Daq the mu' vo' joH'a', nuq ghaH jatlhta' Sum Daj toy'wI' Ahijah the leghwI'pu'.",
        19: "The leS vo' the ta'mey vo' Jeroboam, chay' ghaH warred, je chay' ghaH che'ta', yIlegh, chaH 'oH ghItlhta' Daq the paq vo' the chronicles vo' the joHpu' vo' Israel.",
        20: "The jajmey nuq Jeroboam che'ta' were cha' je cha'maH DISmey: je ghaH Qongta' tlhej Daj vavpu', je Nadab Daj puqloD che'ta' Daq Daj Daq.",
        21: "Rehoboam the puqloD vo' Solomon che'ta' Daq Judah. Rehoboam ghaHta' loSmaH- wa' DISmey qan ghorgh ghaH taghta' Daq che', je ghaH che'ta' seventeen DISmey Daq Jerusalem, the veng nuq joH'a' ghajta' wIvpu' pa' vo' Hoch the tuqpu' vo' Israel, Daq lan Daj pong pa': je Daj mother's pong ghaHta' Naamah the Ammonitess.",
        22: "Judah ta'ta' vetlh nuq ghaHta' mIghtaHghach Daq the leghpu' vo' joH'a', je chaH provoked ghaH Daq jealousy tlhej chaj yemmey nuq chaH committed, Dung Hoch vetlh chaj vavpu' ghajta' ta'pu'.",
        23: "vaD chaH je chenta' chaH jen Daqmey, je pillars, je Asherim, Daq Hoch jen HuD, je bIng Hoch SuD Sor;",
        24: "je pa' were je sodomites Daq the puH: chaH ta'ta' according Daq Hoch the qabqu'boghghachmey vo' the tuqpu' nuq joH'a' drove pa' qaSpa' the puqpu' vo' Israel.",
        25: "'oH qaSta' Daq the fifth DIS vo' joH Rehoboam, vetlh Shishak joH vo' Egypt ghoSta' Dung Daq Jerusalem;",
        26: "je ghaH tlhapta' DoH the treasures vo' the tuq vo' joH'a', je the treasures vo' the joH tuq; ghaH 'ach tlhapta' DoH Hoch: je ghaH tlhapta' DoH Hoch the shields vo' SuD baS nuq Solomon ghajta' chenmoHta'.",
        27: "joH Rehoboam chenmoHta' Daq chaj Daq shields vo' brass, je committed chaH Daq the ghopmey vo' the HoDpu' vo' the guard, 'Iv polta' the lojmIt vo' the joH tuq.",
        28: "'oH ghaHta' vaj, vetlh as often as the joH mejta' Daq the tuq vo' joH'a', the guard boghmoH chaH, je qempu' chaH DoH Daq the guard chamber.",
        29: "DaH the leS vo' the ta'mey vo' Rehoboam, je Hoch vetlh ghaH ta'ta', aren't chaH ghItlhta' Daq the paq vo' the chronicles vo' the joHpu' vo' Judah?",
        30: "pa' ghaHta' veS joj Rehoboam je Jeroboam continually.",
        31: "Rehoboam Qongta' tlhej Daj vavpu', je ghaHta' buried tlhej Daj vavpu' Daq the veng vo' David: je Daj mother's pong ghaHta' Naamah the Ammonitess. Abijam Daj puqloD che'ta' Daq Daj Daq.",
    },
    15: {
        1: "DaH Daq the eighteenth DIS vo' joH Jeroboam the puqloD vo' Nebat taghta' Abijam Daq che' Dung Judah.",
        2: "wej DISmey che'ta' ghaH Daq Jerusalem: je Daj mother's pong ghaHta' Maacah the puqbe' vo' Abishalom.",
        3: "ghaH yItta' Daq Hoch the yemmey vo' Daj vav, nuq ghaH ghajta' ta'pu' qaSpa' ghaH; je Daj tIq ghaHta' ghobe' perfect tlhej joH'a' Daj joH'a', as the tIq vo' David Daj vav.",
        4: "Nevertheless vaD David's chIch ta'ta' joH'a' Daj joH'a' nob ghaH a lamp Daq Jerusalem, Daq cher Dung Daj puqloD after ghaH, je Daq establish Jerusalem;",
        5: "because David ta'ta' vetlh nuq ghaHta' nIH Daq the mInDu' vo' joH'a', je ta'be' tlhe' aside vo' vay' vetlh ghaH ra'ta' ghaH Hoch the jajmey vo' Daj yIn, except neH Daq the matter vo' Uriah the Hittite.",
        6: "DaH pa' ghaHta' veS joj Rehoboam je Jeroboam Hoch the jajmey vo' Daj yIn.",
        7: "The leS vo' the ta'mey vo' Abijam, je Hoch vetlh ghaH ta'ta', aren't chaH ghItlhta' Daq the paq vo' the chronicles vo' the joHpu' vo' Judah? pa' ghaHta' veS joj Abijam je Jeroboam.",
        8: "Abijam Qongta' tlhej Daj vavpu'; je chaH buried ghaH Daq the veng vo' David: je Asa Daj puqloD che'ta' Daq Daj Daq.",
        9: "Daq the twentieth DIS vo' Jeroboam joH vo' Israel taghta' Asa Daq che' Dung Judah.",
        10: "loSmaH- wa' DISmey che'ta' ghaH Daq Jerusalem: je Daj mother's pong ghaHta' Maacah the puqbe' vo' Abishalom.",
        11: "Asa ta'ta' vetlh nuq ghaHta' nIH Daq the mInDu' vo' joH'a', as ta'ta' David Daj vav.",
        12: "ghaH lan DoH the sodomites pa' vo' the puH, je teqta' Hoch the idols vetlh Daj vavpu' ghajta' chenmoHta'.",
        13: "je Maacah Daj SoS ghaH teqta' vo' taH queen, because ghaH ghajta' chenmoHta' an abominable image vaD an Asherah; je Asa pe' bIng Daj image, je meQqu'pu' 'oH Daq the brook Kidron.",
        14: "'ach the jen Daqmey were ghobe' tlhappu' DoH: nevertheless the tIq vo' Asa ghaHta' perfect tlhej joH'a' Hoch Daj jajmey.",
        15: "ghaH qempu' Daq the tuq vo' joH'a' the Dochmey vetlh Daj vav ghajta' dedicated, je the Dochmey vetlh himself ghajta' dedicated, baS chIS, je SuD baS, je Dujmey.",
        16: "pa' ghaHta' veS joj Asa je Baasha joH vo' Israel Hoch chaj jajmey.",
        17: "Baasha joH vo' Israel mejta' Dung Daq Judah, je chenta' Ramah, vetlh ghaH might ghobe' allow anyone Daq jaH pa' joq ghoS Daq Daq Asa joH vo' Judah.",
        18: "vaj Asa tlhapta' Hoch the baS chIS je the SuD baS vetlh were poS Daq the treasures vo' the tuq vo' joH'a', je the treasures vo' the joH tuq, je toDta' chaH Daq the ghop vo' Daj toy'wI'pu'; je joH Asa ngeHta' chaH Daq Ben Hadad, the puqloD vo' Tabrimmon, the puqloD vo' Hezion, joH vo' Syria, 'Iv yInta' Daq Damascus, ja'ta',",
        19: "“pa' ghaH a treaty joj jIH je SoH, joj wIj vav je lIj vav. yIlegh, jIH ghaj ngeHta' Daq SoH a present vo' baS chIS je SuD baS. jaH, ghor lIj treaty tlhej Baasha joH vo' Israel, vetlh ghaH may mej vo' jIH.”",
        20: "Ben Hadad listened Daq joH Asa, je ngeHta' the HoDpu' vo' Daj armies Daq the vengmey vo' Israel, je struck Ijon, je Dan, je Abel Beth Maacah, je Hoch Chinneroth, tlhej Hoch the puH vo' Naphtali.",
        21: "'oH qaSta', ghorgh Baasha Qoyta' vo' 'oH, vetlh ghaH poS litHa' building Ramah, je yInta' Daq Tirzah.",
        22: "vaj joH Asa chenmoHta' a proclamation Daq Hoch Judah; pagh ghaHta' exempted: je chaH qengta' DoH the naghmey vo' Ramah, je its timber, tlhej nuq Baasha ghajta' chenta'; je joH Asa chenta' therewith Geba vo' Benjamin, je Mizpah.",
        23: "DaH the leS vo' Hoch the ta'mey vo' Asa, je Hoch Daj might, je Hoch vetlh ghaH ta'ta', je the vengmey nuq ghaH chenta', aren't chaH ghItlhta' Daq the paq vo' the chronicles vo' the joHpu' vo' Judah? 'ach Daq the poH vo' Daj qan age ghaH ghaHta' diseased Daq Daj qamDu'.",
        24: "Asa Qongta' tlhej Daj vavpu', je ghaHta' buried tlhej Daj vavpu' Daq the veng vo' David Daj vav; je Jehoshaphat Daj puqloD che'ta' Daq Daj Daq.",
        25: "Nadab the puqloD vo' Jeroboam taghta' Daq che' Dung Israel Daq the cha'DIch DIS vo' Asa joH vo' Judah; je ghaH che'ta' Dung Israel cha' DISmey.",
        26: "ghaH ta'ta' vetlh nuq ghaHta' mIghtaHghach Daq the leghpu' vo' joH'a', je yItta' Daq the way vo' Daj vav, je Daq Daj yem tlhej nuq ghaH chenmoHta' Israel Daq yem.",
        27: "Baasha the puqloD vo' Ahijah, vo' the tuq vo' Issachar, conspired Daq ghaH; je Baasha struck ghaH Daq Gibbethon, nuq belonged Daq the Philistines; vaD Nadab je Hoch Israel were laying siege Daq Gibbethon.",
        28: "'ach Daq the wejDIch DIS vo' Asa joH vo' Judah ta'ta' Baasha HoH ghaH, je che'ta' Daq Daj Daq.",
        29: "'oH qaSta' vetlh, as soon as ghaH ghaHta' joH, ghaH struck Hoch the tuq vo' Jeroboam: ghaH ta'be' mej Daq Jeroboam vay' 'Iv breathed, until ghaH ghajta' Qaw'ta' ghaH; according Daq the ja'ta' vo' joH'a', nuq ghaH jatlhta' Sum Daj toy'wI' Ahijah the Shilonite;",
        30: "vaD the yemmey vo' Jeroboam nuq ghaH yempu', je tlhej nuq ghaH chenmoHta' Israel Daq yem, because vo' Daj provocation tlhej nuq ghaH provoked joH'a', the joH'a' vo' Israel, Daq QeH.",
        31: "DaH the leS vo' the ta'mey vo' Nadab, je Hoch vetlh ghaH ta'ta', aren't chaH ghItlhta' Daq the paq vo' the chronicles vo' the joHpu' vo' Israel?",
        32: "pa' ghaHta' veS joj Asa je Baasha joH vo' Israel Hoch chaj jajmey.",
        33: "Daq the wejDIch DIS vo' Asa joH vo' Judah taghta' Baasha the puqloD vo' Ahijah Daq che' Dung Hoch Israel Daq Tirzah, je che'ta' cha'maH- loS DISmey.",
        34: "ghaH ta'ta' vetlh nuq ghaHta' mIghtaHghach Daq the leghpu' vo' joH'a', je yItta' Daq the way vo' Jeroboam, je Daq Daj yem tlhej nuq ghaH chenmoHta' Israel Daq yem.",
    },
    16: {
        1: "The mu' vo' joH'a' ghoSta' Daq Jehu the puqloD vo' Hanani Daq Baasha, ja'ta',",
        2: "“Because jIH exalted SoH pa' vo' the dust, je chenmoHta' SoH joHHom Dung wIj ghotpu Israel, je SoH ghaj yItta' Daq the way vo' Jeroboam, je ghaj chenmoHta' wIj ghotpu Israel Daq yem, Daq provoke jIH Daq QeH tlhej chaj yemmey;",
        3: "yIlegh, jIH DichDaq utterly sweep DoH Baasha je Daj tuq; je jIH DichDaq chenmoH lIj tuq rur the tuq vo' Jeroboam the puqloD vo' Nebat.",
        4: "The dogs DichDaq Sop Baasha's descendants 'Iv Hegh Daq the veng; je ghaH 'Iv dies vo' Daj Daq the yotlh the toQmey vo' the sky DichDaq Sop.”",
        5: "DaH the leS vo' the ta'mey vo' Baasha, je nuq ghaH ta'ta', je Daj might, aren't chaH ghItlhta' Daq the paq vo' the chronicles vo' the joHpu' vo' Israel?",
        6: "Baasha Qongta' tlhej Daj vavpu', je ghaHta' buried Daq Tirzah; je Elah Daj puqloD che'ta' Daq Daj Daq.",
        7: "Moreover Sum the leghwI'pu' Jehu the puqloD vo' Hanani ghoSta' the mu' vo' joH'a' Daq Baasha, je Daq Daj tuq, both because vo' Hoch the mIghtaHghach vetlh ghaH ta'ta' Daq the leghpu' vo' joH'a', Daq provoke ghaH Daq QeH tlhej the vum vo' Daj ghopmey, Daq taH rur the tuq vo' Jeroboam, je because ghaH struck ghaH.",
        8: "Daq the cha'maH- javDich DIS vo' Asa joH vo' Judah taghta' Elah the puqloD vo' Baasha Daq che' Dung Israel Daq Tirzah, je che'ta' cha' DISmey.",
        9: "Daj toy'wI' Zimri, HoD vo' bID Daj Dujmey, conspired Daq ghaH. DaH ghaH ghaHta' Daq Tirzah, drinking himself drunk Daq the tuq vo' Arza, 'Iv ghaHta' Dung the household Daq Tirzah:",
        10: "je Zimri mejta' Daq je struck ghaH, je HoHta' ghaH, Daq the cha'maH- SochDIch DIS vo' Asa joH vo' Judah, je che'ta' Daq Daj Daq.",
        11: "'oH qaSta', ghorgh ghaH taghta' Daq che', as soon as ghaH ba'ta' Daq Daj quS'a', vetlh ghaH struck Hoch the tuq vo' Baasha: ghaH ta'be' mej ghaH a single wa' 'Iv urinates Daq a reD, { Note: joq, male } ghobe' vo' Daj relatives, ghobe' vo' Daj friends.",
        12: "Thus Zimri Qaw'ta' Hoch the tuq vo' Baasha, according Daq the mu' vo' joH'a', nuq ghaH jatlhta' Daq Baasha Sum Jehu the leghwI'pu',",
        13: "vaD Hoch the yemmey vo' Baasha, je the yemmey vo' Elah Daj puqloD, nuq chaH yempu', je tlhej nuq chaH chenmoHta' Israel Daq yem, Daq provoke joH'a', the joH'a' vo' Israel, Daq QeH tlhej chaj vanities.",
        14: "DaH the leS vo' the ta'mey vo' Elah, je Hoch vetlh ghaH ta'ta', aren't chaH ghItlhta' Daq the paq vo' the chronicles vo' the joHpu' vo' Israel?",
        15: "Daq the cha'maH- SochDIch DIS vo' Asa joH vo' Judah ta'ta' Zimri che' Soch jajmey Daq Tirzah. DaH the ghotpu were Dabta' Daq Gibbethon, nuq belonged Daq the Philistines.",
        16: "The ghotpu 'Iv were Dabta' Qoyta' jatlh, Zimri ghajtaH conspired, je ghajtaH je struck the joH: vaj Hoch Israel chenmoHta' Omri, the HoD vo' the army, joH Dung Israel vetlh jaj Daq the raQ.",
        17: "Omri mejta' Dung vo' Gibbethon, je Hoch Israel tlhej ghaH, je chaH qatpu' Tirzah.",
        18: "'oH qaSta', ghorgh Zimri leghta' vetlh the veng ghaHta' tlhappu', vetlh ghaH mejta' Daq the castle vo' the joH tuq, je meQqu'pu' the joH tuq Dung ghaH tlhej qul, je Heghta',",
        19: "vaD Daj yemmey nuq ghaH yempu' Daq doing vetlh nuq ghaHta' mIghtaHghach Daq the leghpu' vo' joH'a', Daq walking Daq the way vo' Jeroboam, je Daq Daj yem nuq ghaH ta'ta', Daq chenmoH Israel Daq yem.",
        20: "DaH the leS vo' the ta'mey vo' Zimri, je Daj treason vetlh ghaH ta'ta', aren't chaH ghItlhta' Daq the paq vo' the chronicles vo' the joHpu' vo' Israel?",
        21: "vaj were the ghotpu vo' Israel divided Daq cha' parts: bID vo' the ghotpu tlha'ta' Tibni the puqloD vo' Ginath, Daq chenmoH ghaH joH; je bID tlha'ta' Omri.",
        22: "'ach the ghotpu 'Iv tlha'ta' Omri prevailed Daq the ghotpu 'Iv tlha'ta' Tibni the puqloD vo' Ginath: vaj Tibni Heghta', je Omri che'ta'.",
        23: "Daq the wejmaH- wa'Dich DIS vo' Asa joH vo' Judah taghta' Omri Daq che' Dung Israel, je che'ta' cha' wa'maH DISmey: jav DISmey che'ta' ghaH Daq Tirzah.",
        24: "ghaH je'ta' the HuD Samaria vo' Shemer vaD cha' talents vo' baS chIS; je ghaH chenta' Daq the HuD, je ja' the pong vo' the veng nuq ghaH chenta', after the pong vo' Shemer, the ghajwI' vo' the HuD, Samaria.",
        25: "Omri ta'ta' vetlh nuq ghaHta' mIghtaHghach Daq the leghpu' vo' joH'a', je dealt wickedly Dung Hoch 'Iv were qaSpa' ghaH.",
        26: "vaD ghaH yItta' Daq Hoch the way vo' Jeroboam the puqloD vo' Nebat, je Daq Daj yemmey tlhej nuq ghaH chenmoHta' Israel Daq yem, Daq provoke joH'a', the joH'a' vo' Israel, Daq QeH tlhej chaj vanities.",
        27: "DaH the leS vo' the ta'mey vo' Omri nuq ghaH ta'ta', je Daj might vetlh ghaH showed, aren't chaH ghItlhta' Daq the paq vo' the chronicles vo' the joHpu' vo' Israel?",
        28: "vaj Omri Qongta' tlhej Daj vavpu', je ghaHta' buried Daq Samaria; je Ahab Daj puqloD che'ta' Daq Daj Daq.",
        29: "Daq the wejmaH-eighth DIS vo' Asa joH vo' Judah taghta' Ahab the puqloD vo' Omri Daq che' Dung Israel: je Ahab the puqloD vo' Omri che'ta' Dung Israel Daq Samaria cha'maH- cha' DISmey.",
        30: "Ahab the puqloD vo' Omri ta'ta' vetlh nuq ghaHta' mIghtaHghach Daq the leghpu' vo' joH'a' Dung Hoch vetlh were qaSpa' ghaH.",
        31: "'oH qaSta', as chugh 'oH ghajta' taH a wov Doch vaD ghaH Daq yIt Daq the yemmey vo' Jeroboam the puqloD vo' Nebat, vetlh ghaH tlhapta' as be'nal Jezebel the puqbe' vo' Ethbaal joH vo' the Sidonians, je mejta' je served Baal, je worshiped ghaH.",
        32: "ghaH reared Dung an lalDanta' Daq vaD Baal Daq the tuq vo' Baal, nuq ghaH ghajta' chenta' Daq Samaria.",
        33: "Ahab chenmoHta' the Asherah; je Ahab ta'ta' yet latlh Daq provoke joH'a', the joH'a' vo' Israel, Daq QeH than Hoch the joHpu' vo' Israel 'Iv were qaSpa' ghaH.",
        34: "Daq Daj jajmey ta'ta' Hiel the Bethelite chen Jericho: ghaH laid its foundation tlhej the loss vo' Abiram Daj firstborn, je cher Dung its lojmItmey tlhej the loss vo' Daj youngest puqloD Segub, according Daq the mu' vo' joH'a', nuq ghaH jatlhta' Sum Joshua the puqloD vo' Nun.",
    },
    17: {
        1: "Elijah the Tishbite, 'Iv ghaHta' vo' the foreigners vo' Gilead, ja'ta' Daq Ahab, “As joH'a', the joH'a' vo' Israel, yIn, qaSpa' 'Iv jIH Qam, pa' DIchDaq ghobe' taH dew ghobe' rain Dochvammey DISmey, 'ach according Daq wIj mu'.”",
        2: "The mu' vo' joH'a' ghoSta' Daq ghaH, ja'ta',",
        3: "“jaH DoH vo' naDev, tlhe' eastward, je So' SoH'egh Sum the brook Cherith, vetlh ghaH qaSpa' the Jordan.",
        4: "'oH DIchDaq taH, vetlh SoH DIchDaq tlhutlh vo' the brook. jIH ghaj ra'ta' the ravens Daq feed SoH pa'.”",
        5: "vaj ghaH mejta' je ta'ta' according Daq the mu' vo' joH'a'; vaD ghaH mejta' je yInta' Sum the brook Cherith, vetlh ghaH qaSpa' the Jordan.",
        6: "The ravens qempu' ghaH tIr Soj je ghab Daq the po, je tIr Soj je ghab Daq the evening; je ghaH drank vo' the brook.",
        7: "'oH qaSta' after a qaStaHvIS, vetlh the brook dried Dung, because pa' ghaHta' ghobe' rain Daq the puH.",
        8: "The mu' vo' joH'a' ghoSta' Daq ghaH, ja'ta',",
        9: "“Hu', jaH Daq Zarephath, nuq belongs Daq Sidon, je stay pa'. yIlegh, jIH ghaj ra'ta' a Heghbe'nal pa' Daq sustain SoH.”",
        10: "vaj ghaH Hu' je mejta' Daq Zarephath; je ghorgh ghaH ghoSta' Daq the lojmIt vo' the veng, yIlegh, a Heghbe'nal ghaHta' pa' gathering sticks: je ghaH ja' Daq Daj, je ja'ta', “Please tlhap jIH a mach bIQ Daq a vessel, vetlh jIH may tlhutlh.”",
        11: "As ghaH ghaHta' ghoS Daq tlhap 'oH, ghaH ja' Daq Daj, je ja'ta', “Please qem jIH a morsel vo' tIr Soj Daq lIj ghop.”",
        12: "ghaH ja'ta', “As joH'a' lIj joH'a' yIn, jIH yImev ghaj a cake, 'ach a handful vo' 'uQ Daq the jar, je a mach Hergh Daq the jar. yIlegh, jIH 'oH gathering cha' sticks, vetlh jIH may jaH Daq je vut 'oH vaD jIH je wIj puqloD, vetlh maH may Sop 'oH, je Hegh.”",
        13: "Elijah ja'ta' Daq Daj, “yImev taH vIp. jaH je ta' as SoH ghaj ja'ta'; 'ach chenmoH jIH vo' 'oH a mach cake wa'Dich, je qem 'oH pa' Daq jIH, je afterward chenmoH 'op vaD SoH je vaD lIj puqloD.",
        14: "vaD thus jatlhtaH joH'a', the joH'a' vo' Israel, ‘The jar vo' 'uQ DIchDaq ghobe' empty, ghobe' DIchDaq the jar vo' Hergh fail, until the jaj vetlh joH'a' sends rain Daq the tera'.'”",
        15: "ghaH mejta' je ta'ta' according Daq the ja'ta' vo' Elijah: je ghaH, je ghaH, je Daj tuq, ate law' jajmey.",
        16: "The jar vo' 'uQ ta'be' empty, ghobe' ta'ta' the jar vo' Hergh fail, according Daq the mu' vo' joH'a', nuq ghaH jatlhta' Sum Elijah.",
        17: "'oH qaSta' after Dochvammey Dochmey, vetlh the puqloD vo' the be', the mistress vo' the tuq, pumta' rop; je Daj sickness ghaHta' vaj 'oy', vetlh pa' ghaHta' ghobe' breath poS Daq ghaH.",
        18: "ghaH ja'ta' Daq Elijah, “nuq ghaj jIH Daq ta' tlhej SoH, SoH loD vo' joH'a'? SoH ghaj ghoS Daq jIH Daq qem wIj yem Daq memory, je Daq HoH wIj puqloD!”",
        19: "ghaH ja'ta' Daq Daj, “nob jIH lIj puqloD.” ghaH tlhapta' ghaH pa' vo' Daj bosom, je qengta' ghaH Dung Daq the room nuqDaq ghaH stayed, je laid ghaH Daq Daj ghaj bed.",
        20: "ghaH SaQta' Daq joH'a', je ja'ta', “joH'a' wIj joH'a', ghaj SoH je qempu' mIghtaHghach Daq the Heghbe'nal tlhej 'Iv jIH sojourn, Sum killing Daj puqloD?”",
        21: "ghaH stretched himself Daq the puq wej poHmey, je SaQta' Daq joH'a', je ja'ta', “joH'a' wIj joH'a', please chaw' vam child's qa' ghoS Daq ghaH again.”",
        22: "joH'a' listened Daq the ghogh vo' Elijah; je the qa' vo' the puq ghoSta' Daq ghaH again, je ghaH revived.",
        23: "Elijah tlhapta' the puq, je qempu' ghaH bIng pa' vo' the chamber Daq the tuq, je toDta' ghaH Daq Daj SoS; je Elijah ja'ta', “yIlegh, lIj puqloD yIn.”",
        24: "The be' ja'ta' Daq Elijah, “DaH jIH Sov vetlh SoH 'oH a loD vo' joH'a', je vetlh the mu' vo' joH'a' Daq lIj nujDu' ghaH vIt.”",
    },
    18: {
        1: "'oH qaSta' after law' jajmey, vetlh the mu' vo' joH'a' ghoSta' Daq Elijah, Daq the wejDIch DIS, ja'ta', “jaH, cha' SoH'egh Daq Ahab; je jIH DichDaq ngeH rain Daq the tera'.”",
        2: "Elijah mejta' Daq cha' himself Daq Ahab. The famine ghaHta' severe Daq Samaria.",
        3: "Ahab ja' Obadiah, 'Iv ghaHta' Dung the household. (DaH Obadiah feared joH'a' greatly:",
        4: "vaD 'oH ghaHta' vaj, ghorgh Jezebel pe' litHa' the leghwI'pu' vo' joH'a', vetlh Obadiah tlhapta' wa' vatlh leghwI'pu', je hid chaH Sum vaghmaH Daq a cave, je Sopta' chaH tlhej tIr Soj je bIQ.)",
        5: "Ahab ja'ta' Daq Obadiah, “jaH vegh the puH, Daq Hoch the springs vo' bIQ, je Daq Hoch the brooks. Perhaps maH may tu' grass je toD the horses je mules yIn, vetlh maH ghobe' lose Hoch the Ha'DIbaH.”",
        6: "vaj chaH divided the puH joj chaH Daq juS throughout 'oH: Ahab mejta' wa' way Sum himself, je Obadiah mejta' another way Sum himself.",
        7: "As Obadiah ghaHta' Daq the way, yIlegh, Elijah met ghaH: je ghaH recognized ghaH, je pumta' Daq Daj qab, je ja'ta', “ghaH 'oH SoH, wIj joH Elijah?”",
        8: "ghaH jangta' ghaH, “'oH ghaH jIH. jaH, ja' lIj joH, ‘yIlegh, Elijah ghaH naDev!'”",
        9: "ghaH ja'ta', “Wherein ghaj jIH yempu', vetlh SoH would toD lIj toy'wI' Daq the ghop vo' Ahab, Daq HoH jIH?",
        10: "As joH'a' lIj joH'a' yIn, pa' ghaH ghobe' Hatlh joq kingdom, nuqDaq wIj joH ghajtaH ghobe' ngeHta' Daq nej SoH. ghorgh chaH ja'ta', ‘ghaH ghaH ghobe' naDev,' ghaH tlhapta' an oath vo' the kingdom je Hatlh, vetlh chaH ta'be' tu' SoH.",
        11: "DaH SoH jatlh, ‘jaH, ja' lIj joH, “yIlegh, Elijah ghaH naDev.”'",
        12: "'oH DichDaq qaS, as soon as jIH 'oH ghoSta' vo' SoH, vetlh the qa' vo' joH'a' DichDaq carry SoH jIH yImev Sov nuqDaq; je vaj ghorgh jIH ghoS je ja' Ahab, je ghaH ta'laHbe' tu' SoH, ghaH DichDaq HoH jIH. 'ach jIH, lIj toy'wI', ghaj feared joH'a' vo' wIj youth.",
        13: "Wasn't 'oH ja'ta' wIj joH nuq jIH ta'ta' ghorgh Jezebel HoHta' the leghwI'pu' vo' joH'a', chay' jIH hid wa' vatlh loDpu' vo' joH'a' leghwI'pu' tlhej vaghmaH Daq a cave, je Sopta' chaH tlhej tIr Soj je bIQ?",
        14: "DaH SoH jatlh, ‘jaH, ja' lIj joH, “yIlegh, Elijah ghaH naDev;”' je ghaH DichDaq HoH jIH.”",
        15: "Elijah ja'ta', “As joH'a' vo' Armies yIn, qaSpa' 'Iv jIH Qam, jIH DichDaq DIch cha' jIH'egh Daq ghaH DaHjaj.”",
        16: "vaj Obadiah mejta' Daq ghom Ahab, je ja'ta' ghaH; je Ahab mejta' Daq ghom Elijah.",
        17: "'oH qaSta', ghorgh Ahab leghta' Elijah, vetlh Ahab ja'ta' Daq ghaH, “ghaH vetlh SoH, SoH troubler vo' Israel?”",
        18: "ghaH jangta', “jIH ghaj ghobe' troubled Israel; 'ach SoH, je lIj vav tuq, Daq vetlh SoH ghaj lonta' the ra'ta'ghach mu'mey vo' joH'a', je SoH ghaj tlha'ta' the Baals.",
        19: "DaH vaj ngeH, je tay'moH Daq jIH Hoch Israel Daq Mount Carmel, je loS vatlh vaghmaH vo' the leghwI'pu' vo' Baal, je loS vatlh vo' the leghwI'pu' vo' the Asherah, 'Iv Sop Daq Jezebel's SopDaq.”",
        20: "vaj Ahab ngeHta' Daq Hoch the puqpu' vo' Israel, je boSta' the leghwI'pu' tay' Daq Mount Carmel.",
        21: "Elijah ghoSta' Sum Daq Hoch the ghotpu, je ja'ta', “chay' tIq DichDaq SoH waver joj the cha' sides? chugh joH'a' ghaH joH'a', tlha' ghaH; 'ach chugh Baal, vaj tlha' ghaH.” The ghotpu jangta' ghaH ghobe' a mu'.",
        22: "vaj Elijah ja'ta' Daq the ghotpu, “jIH, 'ach jIH neH, 'oH poS a leghwI'pu' vo' joH'a'; 'ach Baal's leghwI'pu' 'oH loS vatlh vaghmaH loDpu'.",
        23: "chaw' chaH vaj nob maH cha' Qa'mey; je chaw' chaH choose wa' bull vaD themselves, je pe' 'oH Daq pieces, je lay 'oH Daq the wood, je lan ghobe' qul bIng; je jIH DichDaq dress the latlh bull, je lay 'oH Daq the wood, je lan ghobe' qul bIng 'oH.",
        24: "SoH ja' Daq the pong vo' lIj joH'a', je jIH DichDaq ja' Daq the pong vo' joH'a'. The joH'a' 'Iv answers Sum qul, chaw' ghaH taH joH'a'.” Hoch the ghotpu jangta', “'oH ghaH QaQ ja'ta'.”",
        25: "Elijah ja'ta' Daq the leghwI'pu' vo' Baal, “Choose wa' bull vaD tlhIH'egh, je dress 'oH wa'Dich; vaD SoH 'oH law'; je ja' Daq the pong vo' lIj joH'a', 'ach lan ghobe' qul bIng 'oH.”",
        26: "chaH tlhapta' the bull nuq ghaHta' nobpu' chaH, je chaH dressed 'oH, je ja' Daq the pong vo' Baal vo' po 'ach until DungluQ, ja'ta', Baal, Qoy maH. 'ach pa' ghaHta' ghobe' ghogh, ghobe' vay' 'Iv jangta'. chaH leaped about the lalDanta' Daq nuq ghaHta' chenmoHta'.",
        27: "'oH qaSta' Daq DungluQ, vetlh Elijah mocked chaH, je ja'ta', “SaQ QoymoHlaHbogh; vaD ghaH ghaH a joH'a'. Either ghaH ghaH musing, joq ghaH ghajtaH ghoSta' aside, joq ghaH ghaH Daq a journey, joq perhaps ghaH QongtaH je must taH awakened.”",
        28: "chaH SaQta' QoymoHlaHbogh, je pe' themselves after chaj Da tlhej knives je lances, until the 'Iw gushed pa' Daq chaH.",
        29: "'oH ghaHta' vaj, ghorgh midday ghaHta' past, vetlh chaH prophesied until the poH vo' the cha'nob vo' the cha'nob; 'ach pa' ghaHta' ghobe' ghogh, ghobe' vay' Daq jang, ghobe' vay' 'Iv regarded.",
        30: "Elijah ja'ta' Daq Hoch the ghotpu, “ghoS Sum Daq jIH;” je Hoch the ghotpu ghoSta' Sum Daq ghaH. ghaH repaired the lalDanta' Daq vo' joH'a' vetlh ghaHta' thrown bIng.",
        31: "Elijah tlhapta' cha' wa'maH naghmey, according Daq the mI' vo' the tuqpu' vo' the puqloDpu' vo' Jacob, Daq 'Iv the mu' vo' joH'a' ghoSta', ja'ta', “Israel DIchDaq taH lIj pong.”",
        32: "tlhej the naghmey ghaH chenta' an lalDanta' Daq Daq the pong vo' joH'a'. ghaH chenmoHta' a trench around the lalDanta' Daq, large yap Daq contain cha' juvtaH vo' tIr.",
        33: "ghaH lan the wood Daq order, je pe' the bull Daq pieces, je laid 'oH Daq the wood. ghaH ja'ta', “Fill loS jars tlhej bIQ, je pour 'oH Daq the meQqu'pu' cha'nob, je Daq the wood.”",
        34: "ghaH ja'ta', “ta' 'oH a cha'DIch poH;” je chaH ta'ta' 'oH the cha'DIch poH. ghaH ja'ta', “ta' 'oH a wejDIch poH;” je chaH ta'ta' 'oH the wejDIch poH.",
        35: "The bIQ ran around the lalDanta' Daq; je ghaH je tebta' the trench tlhej bIQ.",
        36: "'oH qaSta' Daq the poH vo' the cha'nob vo' the cha'nob, vetlh Elijah the leghwI'pu' ghoSta' Sum, je ja'ta', “joH'a', the joH'a' vo' Abraham, vo' Isaac, je vo' Israel, chaw' 'oH taH Sovta' vam jaj vetlh SoH 'oH joH'a' Daq Israel, je vetlh jIH 'oH lIj toy'wI', je vetlh jIH ghaj ta'pu' Hoch Dochvammey Dochmey Daq lIj mu'.",
        37: "Qoy jIH, joH'a', Qoy jIH, vetlh vam ghotpu may Sov vetlh SoH, joH'a', 'oH joH'a', je vetlh SoH ghaj tlhe'ta' chaj tIq DoH again.”",
        38: "vaj the qul vo' joH'a' pumta', je Soppu' the meQqu'pu' cha'nob, je the wood, je the naghmey, je the dust, je licked Dung the bIQ vetlh ghaHta' Daq the trench.",
        39: "ghorgh Hoch the ghotpu leghta' 'oH, chaH pumta' Daq chaj faces. chaH ja'ta', “joH'a', ghaH ghaH joH'a'! joH'a', ghaH ghaH joH'a'!”",
        40: "Elijah ja'ta' Daq chaH, “Seize the leghwI'pu' vo' Baal! yImev chaw' wa' vo' chaH escape!” chaH seized chaH. Elijah qempu' chaH bIng Daq the brook Kishon, je HoHta' chaH pa'.",
        41: "Elijah ja'ta' Daq Ahab, “tlhap Dung, Sop je tlhutlh; vaD pa' ghaH the wab vo' abundance vo' rain.”",
        42: "vaj Ahab mejta' Dung Daq Sop je Daq tlhutlh. Elijah mejta' Dung Daq the top vo' Carmel; je ghaH bowed himself bIng Daq the tera', je lan Daj qab joj Daj knees.",
        43: "ghaH ja'ta' Daq Daj toy'wI', “jaH Dung DaH, legh toward the biQ'a'.” ghaH mejta' Dung, je nejta', je ja'ta', “pa' ghaH pagh.” ghaH ja'ta', “jaH again” Soch poHmey.",
        44: "'oH qaSta' Daq the SochDIch poH, vetlh ghaH ja'ta', “yIlegh, a mach cloud, rur a man's ghop, ghaH rising pa' vo' the biQ'a'.” ghaH ja'ta', “jaH Dung, ja' Ahab, ‘tlhap ready je jaH bIng, vaj vetlh the rain ta'be' stop SoH.'”",
        45: "'oH qaSta' Daq a mach qaStaHvIS, vetlh the sky grew black tlhej clouds je SuS, je pa' ghaHta' a Dun rain. Ahab rode, je mejta' Daq Jezreel.",
        46: "The ghop vo' joH'a' ghaHta' Daq Elijah; je ghaH tucked Daj cloak Daq Daj belt je ran qaSpa' Ahab Daq the entrance vo' Jezreel.",
    },
    19: {
        1: "Ahab ja'ta' Jezebel Hoch vetlh Elijah ghajta' ta'pu', je chay' ghaH ghajta' HoHta' Hoch the leghwI'pu' tlhej the 'etlh.",
        2: "vaj Jezebel ngeH a messenger Daq Elijah, ja'ta', “vaj chaw' the Qunpu' ta' Daq jIH, je latlh je, chugh jIH yImev chenmoH lIj yIn as the yIn vo' wa' vo' chaH Sum wa'leS about vam poH!”",
        3: "ghorgh ghaH leghta' vetlh, ghaH Hu', je mejta' vaD Daj yIn, je ghoSta' Daq Beersheba, nuq belongs Daq Judah, je poS Daj toy'wI' pa'.",
        4: "'ach ghaH himself mejta' a jaj journey Daq the ngem, je ghoSta' je ba'ta' bIng bIng a juniper Sor: je ghaH requested vaD himself vetlh ghaH might Hegh, je ja'ta', “'oH ghaH yap. DaH, toH joH'a', tlhap DoH wIj yIn; vaD jIH 'oH ghobe' better than wIj vavpu'.”",
        5: "ghaH lay bIng je Qongta' bIng a juniper Sor; je yIlegh, an Duy touched ghaH, je ja'ta' Daq ghaH, “Hu' je Sop!”",
        6: "ghaH nejta', je yIlegh, pa' ghaHta' Daq Daj nach a cake vutta' Daq the coals, je a jar vo' bIQ. ghaH ate je drank, je laid bIng again.",
        7: "The Duy vo' joH'a' ghoSta' again the cha'DIch poH, je touched ghaH, je ja'ta', “Hu' je Sop, because the journey ghaH too Dun vaD SoH.”",
        8: "ghaH Hu', je ate je drank, je mejta' Daq the HoS vo' vetlh Soj loSmaH jajmey je loSmaH nights Daq Horeb the Mount vo' joH'a'.",
        9: "ghaH ghoSta' pa' Daq a cave, je yIntaH pa'; je yIlegh, the mu' vo' joH'a' ghoSta' Daq ghaH, je ghaH ja'ta' Daq ghaH, “nuq 'oH SoH doing naDev, Elijah?”",
        10: "ghaH ja'ta', “jIH ghaj taH very jealous vaD joH'a', the joH'a' vo' Armies; vaD the puqpu' vo' Israel ghaj lonta' lIj lay', thrown bIng lIj altars, je Heghta' lIj leghwI'pu' tlhej the 'etlh. jIH, 'ach jIH neH, 'oH poS; je chaH nej wIj yIn, Daq tlhap 'oH DoH.”",
        11: "ghaH ja'ta', “jaH pa', je Qam Daq the HuD qaSpa' joH'a'.” yIlegh, joH'a' juSta' Sum, je a Dun je HoS SuS tore the Hudmey, je broke Daq pieces the rocks qaSpa' joH'a'; 'ach joH'a' ghaHta' ghobe' Daq the SuS. After the SuS an earthquake; 'ach joH'a' ghaHta' ghobe' Daq the earthquake.",
        12: "After the earthquake a qul juSta'; 'ach joH'a' ghaHta' ghobe' Daq the qul: je after the qul a vIHHa' mach ghogh.",
        13: "'oH ghaHta' vaj, ghorgh Elijah Qoyta' 'oH, vetlh ghaH wrapped Daj qab Daq Daj mantle, je mejta' pa', je Qampu' Daq the entrance vo' the cave. yIlegh, a ghogh ghoSta' Daq ghaH, je ja'ta', “nuq 'oH SoH doing naDev, Elijah?”",
        14: "ghaH ja'ta', “jIH ghaj taH very jealous vaD joH'a', the joH'a' vo' Armies; vaD the puqpu' vo' Israel ghaj lonta' lIj lay', thrown bIng lIj altars, je Heghta' lIj leghwI'pu' tlhej the 'etlh. jIH, 'ach jIH neH, 'oH poS; je chaH nej wIj yIn, Daq tlhap 'oH DoH.”",
        15: "joH'a' ja'ta' Daq ghaH, “jaH, chegh Daq lIj way Daq the ngem vo' Damascus. ghorgh SoH arrive, SoH DIchDaq anoint Hazael Daq taH joH Dung Syria.",
        16: "SoH DIchDaq anoint Jehu the puqloD vo' Nimshi Daq taH joH Dung Israel; je SoH DIchDaq anoint Elisha the puqloD vo' Shaphat vo' Abel Meholah Daq taH leghwI'pu' Daq lIj Daq.",
        17: "'oH DIchDaq qaS, vetlh ghaH 'Iv escapes vo' the 'etlh vo' Hazael, Jehu DichDaq HoH; je ghaH 'Iv escapes vo' the 'etlh vo' Jehu, Elisha DichDaq HoH.",
        18: "Yet DichDaq jIH mej Soch SaD Daq Israel, Hoch the knees nuq ghaj ghobe' bowed Daq Baal, je Hoch nujDu' nuq ghajtaH ghobe' kissed ghaH.”",
        19: "vaj ghaH departed pa', je tu'ta' Elisha the puqloD vo' Shaphat, 'Iv ghaHta' plowing, tlhej cha' wa'maH yoke vo' chemvaH qaSpa' ghaH, je ghaH tlhej the twelfth: je Elijah juSta' Dung Daq ghaH, je chuH Daj mantle Daq ghaH.",
        20: "ghaH poS the chemvaH, je ran after Elijah, je ja'ta', “chaw' jIH please kiss wIj vav je wIj SoS, je vaj jIH DichDaq tlha' SoH.” ghaH ja'ta' Daq ghaH, “jaH DoH again; vaD nuq ghaj jIH ta'pu' Daq SoH?”",
        21: "ghaH cheghta' vo' following ghaH, je tlhapta' the yoke vo' chemvaH, je HoHta' chaH, je boiled chaj ghab tlhej the instruments vo' the chemvaH, je nobta' Daq the ghotpu, je chaH ate. vaj ghaH Hu', je mejta' after Elijah, je served ghaH.",
    },
    20: {
        1: "Ben Hadad the joH vo' Syria boSta' Hoch Daj army tay'; je pa' were wejmaH- cha' joHpu' tlhej ghaH, je horses je Dujmey: je ghaH mejta' Dung je qatpu' Samaria, je Suvta' Daq 'oH.",
        2: 'ghaH ngeHta\' Duypu\' Daq Ahab joH vo\' Israel, Daq the veng, je ja\'ta\' Daq ghaH, "Thus jatlhtaH Ben Hadad,',
        3: "‘lIj baS chIS je lIj SuD baS ghaH mine. lIj be'nalpu' je je lIj puqpu', 'ach the best, 'oH mine.'”",
        4: "The joH vo' Israel jangta', “'oH ghaH according Daq lIj ja'ta', wIj joH, toH joH. jIH 'oH yours, je Hoch vetlh jIH ghaj.”",
        5: "The Duypu' ghoSta' again, je ja'ta', “Ben Hadad jatlhtaH, ‘jIH ngeHta' indeed Daq SoH, ja'ta', “SoH DIchDaq toD jIH lIj baS chIS, je lIj SuD baS, je lIj be'nalpu', je lIj puqpu';",
        6: "'ach jIH DichDaq ngeH wIj toy'wI'pu' Daq SoH wa'leS about vam poH, je chaH DIchDaq search lIj tuq, je the juHmey vo' lIj toy'wI'pu'; je 'oH DIchDaq taH, vetlh whatever ghaH bel Daq lIj mInDu', chaH DIchDaq lan 'oH Daq chaj ghop, je tlhap 'oH DoH.”'”",
        7: "vaj the joH vo' Israel ja' Hoch the quppu' vo' the puH, je ja'ta', “Please notice chay' vam loD seeks mischief; vaD ghaH ngeHta' Daq jIH vaD wIj be'nalpu', je vaD wIj puqpu', je vaD wIj baS chIS, je vaD wIj SuD baS; je jIH ta'be' deny ghaH.”",
        8: "Hoch the quppu' je Hoch the ghotpu ja'ta' Daq ghaH, “yImev 'Ij, ghobe' consent.”",
        9: "vaj ghaH ja'ta' Daq the Duypu' vo' Ben Hadad, “ja' wIj joH the joH, ‘Hoch vetlh SoH ngeHta' vaD Daq lIj toy'wI' Daq the wa'Dich jIH DichDaq ta'; 'ach vam Doch jIH cannot ta'.” The Duypu' departed, je qempu' ghaH DoH the message.",
        10: "Ben Hadad ngeHta' Daq ghaH, je ja'ta', “The Qunpu' ta' vaj Daq jIH, je latlh je, chugh the dust vo' Samaria DIchDaq suffice vaD handfuls vaD Hoch the ghotpu 'Iv tlha' jIH.”",
        11: "The joH vo' Israel jangta', “ja' ghaH, ‘yImev chaw' ghaH 'Iv puts Daq Daj armor brag rur ghaH 'Iv takes 'oH litHa'.”",
        12: "'oH qaSta', ghorgh Ben Hadad Qoyta' vam message, as ghaH ghaHta' drinking, ghaH je the joHpu', Daq the pavilions, vetlh ghaH ja'ta' Daq Daj toy'wI'pu', “ghuH Daq attack!” chaH prepared Daq attack the veng.",
        13: "yIlegh, a leghwI'pu' ghoSta' Sum Daq Ahab joH vo' Israel, je ja'ta', “Thus jatlhtaH joH'a', ‘ghaj SoH leghpu' Hoch vam Dun qevmey? yIlegh, jIH DichDaq toD 'oH Daq lIj ghop vam jaj; je SoH DIchDaq Sov vetlh jIH 'oH joH'a'.'”",
        14: "Ahab ja'ta', “Sum 'Iv?” ghaH ja'ta', “Thus jatlhtaH joH'a', ‘Sum the Qup loDpu' vo' the joHHom vo' the provinces.'” vaj ghaH ja'ta', “'Iv DIchDaq begin the may'?” ghaH jangta', “SoH.”",
        15: "vaj ghaH mustered the Qup loDpu' vo' the joHHom vo' the provinces, je chaH were cha' vatlh je wejmaH- cha'. After chaH, ghaH mustered Hoch the ghotpu, 'ach Hoch the puqpu' vo' Israel, taH Soch SaD.",
        16: "chaH mejta' pa' Daq DungluQ. 'ach Ben Hadad ghaHta' drinking himself drunk Daq the pavilions, ghaH je the joHpu', the wejmaH- cha' joHpu' 'Iv helped ghaH.",
        17: "The Qup loDpu' vo' the joHHom vo' the provinces mejta' pa' wa'Dich; je Ben Hadad ngeHta' pa', je chaH ja'ta' ghaH, ja'ta', “loDpu' 'oH choltaH pa' vo' Samaria.”",
        18: "ghaH ja'ta', “chugh chaH ghaj ghoS pa' vaD roj, tlhap chaH yIn; joq chugh chaH ghaj ghoS pa' vaD veS, tlhappu' chaH yIn.”",
        19: "vaj Dochvammey mejta' pa' vo' the veng, the Qup loDpu' vo' the joHHom vo' the provinces, je the army nuq tlha'ta' chaH.",
        20: "chaH each HoHta' Daj loD. The Syrians Haw'ta', je Israel pursued chaH. Ben Hadad the joH vo' Syria escaped Daq a horse tlhej horsemen.",
        21: "The joH vo' Israel mejta' pa', je struck the horses je Dujmey, je HoHta' the Syrians tlhej a Dun HoHqu'.",
        22: "The leghwI'pu' ghoSta' Sum Daq the joH vo' Israel, je ja'ta' Daq ghaH, “jaH, strengthen SoH'egh, je mark, je legh nuq SoH ta'; vaD Daq the chegh vo' the DIS the joH vo' Syria DichDaq ghoS Dung Daq SoH.”",
        23: "The toy'wI'pu' vo' the joH vo' Syria ja'ta' Daq ghaH, “chaj joH'a' ghaH a joH'a' vo' the hills; vaj chaH were stronger than maH. 'ach chaw' maH Suv Daq chaH Daq the plain, je DIch maH DIchDaq taH stronger than chaH.",
        24: "ta' vam Doch: tlhap the joHpu' DoH, Hoch loD pa' vo' Daj Daq, je lan HoDpu' Daq chaj Daq.",
        25: "Muster an army, rur the army vetlh SoH ghaj lost, horse vaD horse, je chariot vaD chariot. maH DichDaq Suv Daq chaH Daq the plain, je DIch maH DichDaq taH stronger than chaH.” ghaH listened Daq chaj ghogh, je ta'ta' vaj.",
        26: "'oH qaSta' Daq the chegh vo' the DIS, vetlh Ben Hadad mustered the Syrians, je mejta' Dung Daq Aphek, Daq Suv Daq Israel.",
        27: "The puqpu' vo' Israel were mustered, je were provisioned, je mejta' Daq chaH. The puqpu' vo' Israel Dabta' qaSpa' chaH rur cha' mach flocks vo' Qup goats; 'ach the Syrians tebta' the Hatlh.",
        28: "A loD vo' joH'a' ghoSta' Sum je jatlhta' Daq the joH vo' Israel, je ja'ta', “Thus jatlhtaH joH'a', ‘Because the Syrians ghaj ja'ta', “joH'a' ghaH a joH'a' vo' the hills, 'ach ghaH ghaH ghobe' a joH'a' vo' the valleys;” vaj jIH DichDaq toD Hoch vam Dun qevmey Daq lIj ghop, je SoH DIchDaq Sov vetlh jIH 'oH joH'a'.'”",
        29: "chaH Dabta' wa' Dung Daq the latlh Soch jajmey. vaj 'oH ghaHta', vetlh Daq the SochDIch jaj the may' ghaHta' joined; je the puqpu' vo' Israel HoHta' wa' vatlh SaD footmen vo' the Syrians Daq wa' jaj.",
        30: "'ach the leS Haw'ta' Daq Aphek, Daq the veng; je the reD pumta' Daq cha'maH- Soch SaD loDpu' 'Iv were poS. Ben Hadad Haw'ta', je ghoSta' Daq the veng, Daq an inner chamber.",
        31: "Daj toy'wI'pu' ja'ta' Daq ghaH, “legh DaH, maH ghaj Qoyta' vetlh the joHpu' vo' the tuq vo' Israel 'oH merciful joHpu'. Please chaw' maH lan sackcloth Daq maj porghmey, je ropes Daq maj nachDu', je jaH pa' Daq the joH vo' Israel. Maybe ghaH DichDaq toD lIj yIn.”",
        32: "vaj chaH lan sackcloth Daq chaj porghmey je ropes Daq chaj nachDu', je ghoSta' Daq the joH vo' Israel, je ja'ta', “lIj toy'wI' Ben Hadad jatlhtaH, ‘Please chaw' jIH yIn.'” ghaH ja'ta', “ghaH ghaH vIHHa' yIn? ghaH ghaH wIj loDnI'.”",
        33: "DaH the loDpu' observed diligently, je hurried Daq tlhap vam phrase; je chaH ja'ta', “lIj loDnI' Ben Hadad.” vaj ghaH ja'ta', “jaH, qem ghaH.” vaj Ben Hadad ghoSta' pa' Daq ghaH; je ghaH caused ghaH Daq ghoS Dung Daq the chariot.",
        34: "Ben Hadad ja'ta' Daq ghaH, “The vengmey nuq wIj vav tlhapta' vo' lIj vav jIH DichDaq nobHa'. SoH DIchDaq chenmoH streets vaD SoH'egh Daq Damascus, as wIj vav chenmoHta' Daq Samaria.” “jIH,” ja'ta' Ahab, “DichDaq chaw' SoH jaH tlhej vam lay'.” vaj ghaH chenmoHta' a lay' tlhej ghaH, je chaw' ghaH jaH.",
        35: "A Dich loD vo' the puqloDpu' vo' the leghwI'pu' ja'ta' Daq Daj fellow Sum the mu' vo' joH'a', “Please mup jIH!” The loD refused Daq mup ghaH.",
        36: "vaj ja'ta' ghaH Daq ghaH, “Because SoH ghaj ghobe' obeyed the ghogh vo' joH'a', yIlegh, as soon as SoH 'oH departed vo' jIH, a HaDI'baH DIchDaq HoH SoH.” As soon as ghaH ghaHta' departed vo' ghaH, a HaDI'baH tu'ta' ghaH, je HoHta' ghaH.",
        37: "vaj ghaH tu'ta' another loD, je ja'ta', “Please mup jIH.” The loD struck ghaH, smiting je wounding ghaH.",
        38: "vaj the leghwI'pu' departed, je waited vaD the joH Sum the way, je disguised himself tlhej Daj headband Dung Daj mInDu'.",
        39: "As the joH juSta' Sum, ghaH SaQta' Daq the joH; je ghaH ja'ta', “lIj toy'wI' mejta' pa' Daq the midst vo' the may'; je yIlegh, a loD tlhe'ta' aside, je qempu' a loD Daq jIH, je ja'ta', ‘Guard vam loD! chugh Sum vay' means ghaH taH missing, vaj lIj yIn DIchDaq taH vaD Daj yIn, joq else SoH DIchDaq pay a talent vo' baS chIS.'",
        40: "As lIj toy'wI' ghaHta' busy naDev je pa', ghaH ghaHta' ghoSta'.” The joH vo' Israel ja'ta' Daq ghaH, “vaj lIj yoj DIchDaq taH; SoH'egh ghaj decided 'oH.”",
        41: "ghaH hurried, je tlhapta' the headband DoH vo' Daj mInDu'; je the joH vo' Israel recognized vetlh ghaH ghaHta' vo' the leghwI'pu'.",
        42: "ghaH ja'ta' Daq ghaH, “Thus jatlhtaH joH'a', ‘Because SoH ghaj chaw' jaH pa' vo' lIj ghop the loD 'Iv jIH ghajta' devoted Daq QIH, vaj lIj yIn DIchDaq jaH vaD Daj yIn, je lIj ghotpu vaD Daj ghotpu.'”",
        43: "The joH vo' Israel mejta' Daq Daj tuq sullen je angry, je ghoSta' Daq Samaria.",
    },
    21: {
        1: "'oH qaSta' after Dochvammey Dochmey, vetlh Naboth the Jezreelite ghajta' a HIq wIj, nuq ghaHta' Daq Jezreel, hard Sum the palace vo' Ahab joH vo' Samaria.",
        2: "Ahab jatlhta' Daq Naboth, ja'ta', “nob jIH lIj HIq wIj, vetlh jIH may ghaj 'oH vaD a wIjghachHom vo' herbs, because 'oH ghaH Sum Daq wIj tuq; je jIH DichDaq nob SoH vaD 'oH a better HIq wIj than 'oH. joq, chugh 'oH seems QaQ Daq SoH, jIH DichDaq nob SoH its worth Daq Huch.”",
        3: "Naboth ja'ta' Daq Ahab, “May joH'a' forbid jIH, vetlh jIH should nob the inheritance vo' wIj vavpu' Daq SoH!”",
        4: "Ahab ghoSta' Daq Daj tuq sullen je angry because vo' the mu' nuq Naboth the Jezreelite ghajta' jatlhpu' Daq ghaH; vaD ghaH ghajta' ja'ta', “jIH DichDaq ghobe' nob SoH the inheritance vo' wIj vavpu'.” ghaH laid himself bIng Daq Daj bed, je tlhe'ta' DoH Daj qab, je would Sop ghobe' tIr Soj.",
        5: "'ach Jezebel Daj be'nal ghoSta' Daq ghaH, je ja'ta' Daq ghaH, “qatlh ghaH lIj qa' vaj sad, vetlh SoH Sop ghobe' tIr Soj?”",
        6: "ghaH ja'ta' Daq Daj, “Because jIH jatlhta' Daq Naboth the Jezreelite, je ja'ta' Daq ghaH, ‘nob jIH lIj HIq wIj vaD Huch; joq else, chugh 'oH pleases SoH, jIH DichDaq nob SoH another HIq wIj vaD 'oH.' ghaH jangta', ‘jIH DichDaq ghobe' nob SoH wIj HIq wIj.'”",
        7: "Jezebel Daj taH'nal ja'ta' Daq ghaH, “ta' SoH DaH govern the kingdom vo' Israel? Hu', je Sop tIr Soj, je chaw' lIj tIq be yItIv. jIH DichDaq nob SoH the HIq wIj vo' Naboth the Jezreelite.”",
        8: "vaj ghaH wrote letters Daq Ahab's pong, je sealed chaH tlhej Daj seal, je ngeHta' the letters Daq the quppu' je Daq the nobles 'Iv were Daq Daj veng, 'Iv yInta' tlhej Naboth.",
        9: "ghaH wrote Daq the letters, ja'ta', “Proclaim a fast, je cher Naboth Daq jen among the ghotpu.",
        10: "cher cha' loDpu', base fellows, qaSpa' ghaH, je chaw' chaH testify Daq ghaH, ja'ta', ‘SoH cursed joH'a' je the joH!' vaj carry ghaH pa', je nagh ghaH Daq Hegh.”",
        11: "The loDpu' vo' Daj veng, 'ach the quppu' je the nobles 'Iv yInta' Daq Daj veng, ta'ta' as Jezebel ghajta' ngeHta' Daq chaH, according as 'oH ghaHta' ghItlhta' Daq the letters nuq ghaH ghajta' ngeHta' Daq chaH.",
        12: 'chaH proclaimed a fast, je cher Naboth Daq jen among the ghotpu.',
        13: "The cha' loDpu', the base fellows, ghoSta' Daq je ba'ta' qaSpa' ghaH. The base fellows testified Daq ghaH, 'ach Daq Naboth, Daq the Daq vo' the ghotpu, ja'ta', “Naboth cursed joH'a' je the joH!” vaj chaH qengta' ghaH pa' vo' the veng, je stoned ghaH Daq Hegh tlhej naghmey.",
        14: "vaj chaH ngeHta' Daq Jezebel, ja'ta', “Naboth ghajtaH taH stoned, je ghaH Heghpu'.”",
        15: "'oH qaSta', ghorgh Jezebel Qoyta' vetlh Naboth ghaHta' stoned, je ghaHta' Heghpu', vetlh Jezebel ja'ta' Daq Ahab, “Hu', tlhap possession vo' the HIq wIj vo' Naboth the Jezreelite, nuq ghaH refused Daq nob SoH vaD Huch; vaD Naboth ghaH ghobe' yIn, 'ach Heghpu'.”",
        16: "'oH qaSta', ghorgh Ahab Qoyta' vetlh Naboth ghaHta' Heghpu', vetlh Ahab rose Dung Daq jaH bIng Daq the HIq wIj vo' Naboth the Jezreelite, Daq tlhap possession vo' 'oH.",
        17: "The mu' vo' joH'a' ghoSta' Daq Elijah the Tishbite, ja'ta',",
        18: "“Hu', jaH bIng Daq ghom Ahab joH vo' Israel, 'Iv yIntaH Daq Samaria. yIlegh, ghaH ghaH Daq the HIq wIj vo' Naboth, nuqDaq ghaH ghajtaH ghoSta' bIng Daq tlhap possession vo' 'oH.",
        19: "SoH DIchDaq jatlh Daq ghaH, ja'ta', ‘Thus jatlhtaH joH'a', “ghaj SoH HoHta' je je tlhappu' possession?”' SoH DIchDaq jatlh Daq ghaH, ja'ta', ‘Thus jatlhtaH joH'a', “Daq the Daq nuqDaq dogs licked the 'Iw vo' Naboth, dogs DichDaq lick lIj 'Iw, 'ach yours.”'”",
        20: "Ahab ja'ta' Daq Elijah, “ghaj SoH tu'ta' jIH, wIj jagh?” ghaH jangta', “jIH ghaj tu'ta' SoH, because SoH ghaj sold SoH'egh Daq ta' vetlh nuq ghaH mIghtaHghach Daq the leghpu' vo' joH'a'.",
        21: "yIlegh, jIH DichDaq qem mIghtaHghach Daq SoH, je DichDaq utterly sweep SoH DoH je DichDaq pe' litHa' vo' Ahab Hoch 'Iv urinates Daq a reD, { Note: joq, male } je ghaH 'Iv ghaH shut Dung je ghaH 'Iv ghaH poS Daq large Daq Israel.",
        22: "jIH DichDaq chenmoH lIj tuq rur the tuq vo' Jeroboam the puqloD vo' Nebat, je rur the tuq vo' Baasha the puqloD vo' Ahijah vaD the provocation tlhej nuq SoH ghaj provoked jIH Daq QeH, je ghaj chenmoHta' Israel Daq yem.”",
        23: "joH'a' je jatlhta' vo' Jezebel, ja'ta', “The dogs DIchDaq Sop Jezebel Sum the rampart vo' Jezreel.",
        24: "The dogs DichDaq Sop ghaH 'Iv dies vo' Ahab Daq the veng; je the toQmey vo' the sky DichDaq Sop ghaH 'Iv dies Daq the yotlh.”",
        25: "'ach pa' ghaHta' pagh rur Ahab, 'Iv sold himself Daq ta' vetlh nuq ghaHta' mIghtaHghach Daq the leghpu' vo' joH'a', 'Iv Jezebel Daj be'nal stirred Dung.",
        26: "ghaH ta'ta' very abominably Daq following idols, according Daq Hoch vetlh the Amorites ta'ta', 'Iv joH'a' chuH pa' qaSpa' the puqpu' vo' Israel.",
        27: "'oH qaSta', ghorgh Ahab Qoyta' chaH mu'mey, vetlh ghaH tore Daj clothes, je lan sackcloth Daq Daj ghab, je fasted, je lay Daq sackcloth, je mejta' softly.",
        28: "The mu' vo' joH'a' ghoSta' Daq Elijah the Tishbite, ja'ta',",
        29: "“legh chay' Ahab humbles himself qaSpa' jIH? Because ghaH humbles himself qaSpa' jIH, jIH DichDaq ghobe' qem the mIghtaHghach Daq Daj jajmey; 'ach Daq Daj son's jajmey DichDaq jIH qem the mIghtaHghach Daq Daj tuq.”",
    },
    22: {
        1: 'chaH continued wej DISmey Hutlh veS joj Syria je Israel.',
        2: "'oH qaSta' Daq the wejDIch DIS, vetlh Jehoshaphat the joH vo' Judah ghoSta' bIng Daq the joH vo' Israel.",
        3: "The joH vo' Israel ja'ta' Daq Daj toy'wI'pu', “SoH Sov vetlh Ramoth Gilead ghaH ours, je maH 'oH vIHHa', je yImev tlhap 'oH pa' vo' the ghop vo' the joH vo' Syria?”",
        4: "ghaH ja'ta' Daq Jehoshaphat, “DichDaq SoH jaH tlhej jIH Daq may' Daq Ramoth Gilead?” Jehoshaphat ja'ta' Daq the joH vo' Israel, “jIH 'oH as SoH 'oH, wIj ghotpu as lIj ghotpu, wIj horses as lIj horses.”",
        5: "Jehoshaphat ja'ta' Daq the joH vo' Israel, “Please inquire wa'Dich vaD the mu' vo' joH'a'.”",
        6: "vaj the joH vo' Israel boSta' the leghwI'pu' tay', about loS vatlh loDpu', je ja'ta' Daq chaH, “DIchDaq jIH jaH Daq Ramoth Gilead Daq may', joq DIchDaq jIH forbear?” chaH ja'ta', “jaH Dung; vaD the joH DichDaq toD 'oH Daq the ghop vo' the joH.”",
        7: "'ach Jehoshaphat ja'ta', “'oHbe' pa' naDev a leghwI'pu' vo' joH'a', vetlh maH may inquire vo' ghaH?”",
        8: "The joH vo' Israel ja'ta' Daq Jehoshaphat, “pa' ghaH yet wa' loD Sum 'Iv maH may inquire vo' joH'a', Micaiah the puqloD vo' Imlah; 'ach jIH hate ghaH; vaD ghaH ta'taH ghobe' prophesy QaQ concerning jIH, 'ach mIghtaHghach.” Jehoshaphat ja'ta', “yImev chaw' the joH jatlh vaj.”",
        9: "vaj the joH vo' Israel ja' an officer, je ja'ta', “Quickly tlhap Micaiah the puqloD vo' Imlah.”",
        10: "DaH the joH vo' Israel je Jehoshaphat the joH vo' Judah were sitting each Daq Daj quS'a', arrayed Daq chaj robes, Daq an poSmoH Daq Daq the entrance vo' the lojmIt vo' Samaria; je Hoch the leghwI'pu' were prophesying qaSpa' chaH.",
        11: "Zedekiah the puqloD vo' Chenaanah chenmoHta' ghaH horns vo' iron, je ja'ta', “Thus jatlhtaH joH'a', ‘tlhej Dochvammey SoH DIchDaq push the Syrians, until chaH 'oH Soppu'.'”",
        12: "Hoch the leghwI'pu' prophesied vaj, ja'ta', “jaH Dung Daq Ramoth Gilead, je chep; vaD joH'a' DichDaq toD 'oH Daq the ghop vo' the joH.”",
        13: "The messenger 'Iv mejta' Daq ja' Micaiah jatlhta' Daq ghaH, ja'ta', “legh DaH, the the leghwI'pu' declare QaQ Daq the joH tlhej wa' nujDu'. Please chaw' lIj mu' taH rur the mu' vo' wa' vo' chaH, je jatlh QaQ.”",
        14: "Micaiah ja'ta', “As joH'a' yIn, nuq joH'a' jatlhtaH Daq jIH, vetlh jIH DichDaq jatlh.”",
        15: "ghorgh ghaH ghajta' ghoS Daq the joH, the joH ja'ta' Daq ghaH, “Micaiah, DIchDaq maH jaH Daq Ramoth Gilead Daq may', joq DIchDaq maH forbear?” ghaH jangta' ghaH, “jaH Dung je chep; je joH'a' DichDaq toD 'oH Daq the ghop vo' the joH.”",
        16: "The joH ja'ta' Daq ghaH, “chay' law' poHmey ta' jIH ghaj Daq adjure SoH vetlh SoH jatlh Daq jIH pagh 'ach the vIt Daq the pong vo' joH'a'?”",
        17: "ghaH ja'ta', “jIH leghta' Hoch Israel scattered Daq the Hudmey, as Suy' vetlh ghaj ghobe' DevwI'. joH'a' ja'ta', ‘Dochvammey ghaj ghobe' pIn. chaw' chaH each chegh Daq Daj tuq Daq roj.'”",
        18: "The joH vo' Israel ja'ta' Daq Jehoshaphat, “ta'be' jIH ja' SoH vetlh ghaH would ghobe' prophesy QaQ concerning jIH, 'ach mIghtaHghach?”",
        19: "Micaiah ja'ta', “vaj Qoy the mu' vo' joH'a'. jIH leghta' joH'a' sitting Daq Daj quS'a', je Hoch the army vo' chal standing Sum ghaH Daq Daj nIH ghop je Daq Daj poS.",
        20: "joH'a' ja'ta', ‘'Iv DIchDaq entice Ahab, vetlh ghaH may jaH Dung je pum Daq Ramoth Gilead?' wa' ja'ta' wa' Doch; je another ja'ta' another.",
        21: "A qa' ghoSta' pa' je Qampu' qaSpa' joH'a', je ja'ta', ‘jIH DichDaq entice ghaH.'",
        22: "joH'a' ja'ta' Daq ghaH, ‘chay'?' ghaH ja'ta', ‘jIH DichDaq jaH pa' je DichDaq taH a lying qa' Daq the nujDu' vo' Hoch Daj leghwI'pu'.' ghaH ja'ta', ‘SoH DichDaq entice ghaH, je DichDaq je prevail. jaH pa' je ta' vaj.'",
        23: "DaH vaj, yIlegh, joH'a' ghajtaH lan a lying qa' Daq the nujDu' vo' Hoch Dochvammey lIj leghwI'pu'; je joH'a' ghajtaH jatlhpu' mIghtaHghach concerning SoH.”",
        24: "vaj Zedekiah the puqloD vo' Chenaanah ghoSta' Sum, je struck Micaiah Daq the cheek, je ja'ta', “nuq way ta'ta' the qa' vo' joH'a' jaH vo' jIH Daq jatlh Daq SoH?”",
        25: "Micaiah ja'ta', “yIlegh, SoH DichDaq legh Daq vetlh jaj, ghorgh SoH jaH Daq an inner chamber Daq So' SoH'egh.”",
        26: "The joH vo' Israel ja'ta', “tlhap Micaiah, je carry ghaH DoH Daq Amon the governor vo' the veng, je Daq Joash the joH puqloD.",
        27: "jatlh, ‘Thus jatlhtaH the joH, “lan vam fellow Daq the prison, je feed ghaH tlhej tIr Soj vo' affliction je tlhej bIQ vo' affliction, until jIH ghoS Daq roj.”'”",
        28: "Micaiah ja'ta', “chugh SoH chegh Daq Hoch Daq roj, joH'a' ghajtaH ghobe' jatlhpu' Sum jIH.” ghaH ja'ta', “'Ij, Hoch SoH ghotpu!”",
        29: "vaj the joH vo' Israel je Jehoshaphat the joH vo' Judah mejta' Dung Daq Ramoth Gilead.",
        30: "The joH vo' Israel ja'ta' Daq Jehoshaphat, “jIH DichDaq disguise jIH'egh, je jaH Daq the may'; 'ach SoH lan Daq lIj robes.” The joH vo' Israel disguised himself, je mejta' Daq the may'.",
        31: "DaH the joH vo' Syria ghajta' ra'ta' the wejmaH- cha' HoDpu' vo' Daj Dujmey, ja'ta', Suv ghobe' tlhej mach ghobe' Dun, except neH tlhej the joH vo' Israel.",
        32: "'oH qaSta', ghorgh the HoDpu' vo' the Dujmey leghta' Jehoshaphat, vetlh chaH ja'ta', “DIch vetlh ghaH the joH vo' Israel!” je chaH tlhe'ta' aside Daq Suv Daq ghaH. Jehoshaphat SaQta' pa'.",
        33: "'oH qaSta', ghorgh the HoDpu' vo' the Dujmey leghta' vetlh 'oH ghaHta' ghobe' the joH vo' Israel, vetlh chaH tlhe'ta' DoH vo' pursuing ghaH.",
        34: "A Dich loD drew Daj bow Daq random, je struck the joH vo' Israel joj the joints vo' the armor. vaj ghaH ja'ta' Daq the driver vo' Daj chariot, “tlhe' lIj ghop, je carry jIH pa' vo' the may'; vaD jIH 'oH severely wounded.”",
        35: "The may' increased vetlh jaj. The joH ghaHta' propped Dung Daq Daj chariot facing the Syrians, je Heghta' Daq evening. The 'Iw ran pa' vo' the wound Daq the bIng vo' the chariot.",
        36: "A SaQ mejta' throughout the army about the ghoS bIng vo' the pemHov, ja'ta', “Hoch loD Daq Daj veng, je Hoch loD Daq Daj Hatlh!”",
        37: "vaj the joH Heghta', je ghaHta' qempu' Daq Samaria; je chaH buried the joH Daq Samaria.",
        38: "chaH washed the chariot Sum the pool vo' Samaria; je the dogs licked Dung Daj 'Iw nuqDaq the prostitutes washed themselves; according Daq the mu' vo' joH'a' nuq ghaH jatlhta'.",
        39: "DaH the leS vo' the ta'mey vo' Ahab, je Hoch vetlh ghaH ta'ta', je the ivory tuq nuq ghaH chenta', je Hoch the vengmey vetlh ghaH chenta', aren't chaH ghItlhta' Daq the paq vo' the chronicles vo' the joHpu' vo' Israel?",
        40: "vaj Ahab Qongta' tlhej Daj vavpu'; je Ahaziah Daj puqloD che'ta' Daq Daj Daq.",
        41: "Jehoshaphat the puqloD vo' Asa taghta' Daq che' Dung Judah Daq the fourth DIS vo' Ahab joH vo' Israel.",
        42: "Jehoshaphat ghaHta' wejmaH- vagh DISmey qan ghorgh ghaH taghta' Daq che'; je ghaH che'ta' cha'maH- vagh DISmey Daq Jerusalem. Daj mother's pong ghaHta' Azubah the puqbe' vo' Shilhi.",
        43: "ghaH yItta' Daq Hoch the way vo' Asa Daj vav; ghaH ta'be' tlhe' aside vo' 'oH, doing vetlh nuq ghaHta' nIH Daq the mInDu' vo' joH'a': however the jen Daqmey were ghobe' tlhappu' DoH; the ghotpu vIHHa' sacrificed je meQqu'pu' He' Daq the jen Daqmey.",
        44: "Jehoshaphat chenmoHta' roj tlhej the joH vo' Israel.",
        45: "DaH the leS vo' the ta'mey vo' Jehoshaphat, je Daj might vetlh ghaH showed, je chay' ghaH warred, aren't chaH ghItlhta' Daq the paq vo' the chronicles vo' the joHpu' vo' Judah?",
        46: "The chuv vo' the sodomites, vetlh remained Daq the jajmey vo' Daj vav Asa, ghaH lan DoH pa' vo' the puH.",
        47: "pa' ghaHta' ghobe' joH Daq Edom: a deputy ghaHta' joH.",
        48: "Jehoshaphat chenmoHta' ships vo' Tarshish Daq jaH Daq Ophir vaD SuD baS: 'ach chaH ta'be' jaH; vaD the ships were ghorta' Daq Ezion Geber.",
        49: "vaj Ahaziah the puqloD vo' Ahab ja'ta' Daq Jehoshaphat, “chaw' wIj toy'wI'pu' jaH tlhej lIj toy'wI'pu' Daq the ships.” 'ach Jehoshaphat would ghobe'.",
        50: "Jehoshaphat Qongta' tlhej Daj vavpu', je ghaHta' buried tlhej Daj vavpu' Daq the veng vo' David Daj vav; Jehoram Daj puqloD che'ta' Daq Daj Daq.",
        51: "Ahaziah the puqloD vo' Ahab taghta' Daq che' Dung Israel Daq Samaria Daq the seventeenth DIS vo' Jehoshaphat joH vo' Judah, je ghaH che'ta' cha' DISmey Dung Israel.",
        52: "ghaH ta'ta' vetlh nuq ghaHta' mIghtaHghach Daq the leghpu' vo' joH'a', je yItta' Daq the way vo' Daj vav, je Daq the way vo' Daj SoS, je Daq the way vo' Jeroboam the puqloD vo' Nebat, Daq nuq ghaH chenmoHta' Israel Daq yem.",
        53: "ghaH served Baal, je worshiped ghaH, je provoked Daq QeH joH'a', the joH'a' vo' Israel, according Daq Hoch vetlh Daj vav ghajta' ta'pu'.",
    },
}
